INSERT INTO `mg_z_column` VALUES ('1', '踢走失眠·打造好眠空間 (五)', '踢走失眠·打造好眠空間 (五)', '605期 ', '605期 ', '387', '1512662400', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><img style=\"margin-right: 4px;\" src=\"/mas_studio/storage/image/20171216/5a34cbff47f27.jpg\" alt=\"\" width=\"207\" height=\"308\" /><img style=\"margin-right: 4px;\" src=\"/mas_studio/storage/image/20180109/5a547dbbaeb27.jpg\" alt=\"\" width=\"330\" height=\"308\" /><img style=\"margin-right: 4px;\" src=\"data:image/jpeg;base64,\" width=\"299\" height=\"306\" /></p>\r\n<p class=\"MsoNormal\"><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">要打造一個好</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">眠的空間需要考慮上期提及過的床褥及床上用品</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">有助睡眠的柔和燈光</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、窗簾及注意睡房的主要作用</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">之外還有</span><span style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">:</span><br /><br /><!-- [if !supportLists]--><strong><span style=\"mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;\"><span style=\"mso-list: Ignore;\">&nbsp; &nbsp; &nbsp; 1)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">低沉柔和的睡房顏色</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;從心理學的角度，色彩繽紛的顏色給人明快的感覺，所以絕對不合適用於需要</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">放鬆</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">及沉靜的睡房當中。所以選用於睡房的顏色最好是柔和而沉穩的大地色系，或是暖灰色、淡藍、淡綠等低彩度或低明度的色彩。如果真的十分喜愛較明亮的顏色建議只用在範圍較少如</span> Cushion<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、椅子等用品上。</span><br /><br /><strong><!-- [if !supportLists]--><span style=\"mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;\"><span style=\"mso-list: Ignore;\">&nbsp; &nbsp; &nbsp; 2)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">保持房間整潔</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;若睡房內滿是雜物又凌亂不堪的話，會讓人感到煩躁焦慮，除非只有這樣才令你有安全感或感到舒適，否則最好還是整理一下保持睡房簡潔。另外雜物越多積聚的塵蟎也越多，對氣管敏感人仕來說只會加重病情以及更難入睡，所以最好把雜物放在儲物箱內或直接搬離睡房。</span><br /><br /><!-- [if !supportLists]--><strong><span style=\"mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;\"><span style=\"mso-list: Ignore;\">&nbsp; &nbsp; &nbsp; 3)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">有不少老夫妻都已經習慣在同一房間但分開</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">兩</span></strong><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\"><strong>張床睡</strong>，其實不一定要年長的夫妻才分開床睡覺，假若你已經購買了專門分開的床褥仍無法避免因為另一半微微的翻動或轉身影響而醒來的話，</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">而</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">睡房</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">空間</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">許可的話，不妨選擇分開兩張床也是個不錯的選擇。</span><br /><br /><!-- [if !supportLists]--><strong><span style=\"mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;\"><span style=\"mso-list: Ignore;\">&nbsp; &nbsp; &nbsp; 4)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">隔音的問題</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;當一個空間的噪音持續到達</span>30<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">分貝時，就會影響到睡眠，但對不少</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">要輪班工作</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">或住在</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">鬧區</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">的人來說，只可以選擇良好的隔音設備才可以營造到一個較好的睡眠空間。除了選用雙層隔音玻璃的窗戶之外，也可以使用一些具吸音效果的窗簾，也可以隔絕</span>10<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">～</span>20<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">％的外界噪音，而且窗簾的布料越厚，吸音的效果越好，這也是個不錯的選擇。</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">但有些人則需要有點聲音才能入睡，一般會選擇開着電視睡，但往往第二天總是覺得十分睏倦，如果真的如此不妨試用其他聲音作為「白噪音」（</span>white&ensp; noise<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">），例如冷氣機、電風扇等發出的聲音。由於這些聲音都是單調而固定，不像電視所發出的聲音那樣多變，在寂靜與外界聲音之間起到阻隔作用，減少電視突如其來的聲響令你醒來。</span><br /><br /><!-- [if !supportLists]--><span style=\"mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: Calibri; mso-bidi-theme-font: minor-latin;\"><span style=\"mso-list: Ignore;\"><img style=\"font-family: 新細明體; float: left; margin: 1px 0.5 1px 0.5;\" src=\"/mas_studio/storage/image/20171216/5a34cc011ea61.jpg\" width=\"343\" height=\"186\" /><strong>5)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp; </span></strong></span></span><strong><!--[endif]--><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">保持溫暖舒適</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">睡眠時身體的溫度會逐漸下降，所以在清晨臨睡醒前會降至最低，因此房間的溫度要令我們感到舒適，有些專家說</span>25<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">℃</span> <span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">的 室溫最容易入睡，不過每個人的感覺不同，不妨嘗試找尋自己最舒適的睡房溫度。</span><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp;希望這幾篇的資訊可以為大家打造出一個好眠空間每晚也可以發個好夢。</span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><img style=\"margin-right: 4px;\" src=\"/mas_studio/storage/image/20171216/5a34cbff47f27.jpg\" alt=\"\" width=\"207\" height=\"308\" /><img style=\"margin-right: 4px;\" src=\"/mas_studio/storage/image/20180109/5a547dbbaeb27.jpg\" alt=\"\" width=\"330\" height=\"308\" /><img style=\"margin-right: 4px;\" src=\"data:image/jpeg;base64,\" width=\"299\" height=\"306\" /></p>\r\n<p class=\"MsoNormal\"><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">要打造一個好</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">眠的空間需要考慮上期提及過的床褥及床上用品</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">有助睡眠的柔和燈光</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、窗簾及注意睡房的主要作用</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">之外還有</span><span style=\"font-family: 新細明體; mso-ascii-theme-font: minor-fareast; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-hansi-font-family: 新細明體; mso-hansi-theme-font: minor-fareast;\">:</span><br /><br /><strong>&nbsp; &nbsp; &nbsp; 1)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">低沉柔和的睡房顏色</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;從心理學的角度，色彩繽紛的顏色給人明快的感覺，所以絕對不合適用於需要</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">放鬆</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">及沉靜的睡房當中。所以選用於睡房的顏色最好是柔和而沉穩的大地色系，或是暖灰色、淡藍、淡綠等低彩度或低明度的色彩。如果真的十分喜愛較明亮的顏色建議只用在範圍較少如</span>&nbsp;Cushion<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">、椅子等用品上。</span><br /><br /><strong>&nbsp; &nbsp; &nbsp; 2)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">保持房間整潔</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;若睡房內滿是雜物又凌亂不堪的話，會讓人感到煩躁焦慮，除非只有這樣才令你有安全感或感到舒適，否則最好還是整理一下保持睡房簡潔。另外雜物越多積聚的塵蟎也越多，對氣管敏感人仕來說只會加重病情以及更難入睡，所以最好把雜物放在儲物箱內或直接搬離睡房。</span><br /><br /><strong>&nbsp; &nbsp; &nbsp; 3)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">有不少老夫妻都已經習慣在同一房間但分開</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">兩</span></strong><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\"><strong>張床睡</strong>，其實不一定要年長的夫妻才分開床睡覺，假若你已經購買了專門分開的床褥仍無法避免因為另一半微微的翻動或轉身影響而醒來的話，</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">而</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">睡房</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">空間</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">許可的話，不妨選擇分開兩張床也是個不錯的選擇。</span><br /><br /><strong>&nbsp; &nbsp; &nbsp; 4)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">隔音的問題</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">&nbsp; &nbsp; &nbsp; &nbsp;當一個空間的噪音持續到達</span>30<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">分貝時，就會影響到睡眠，但對不少</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">要輪班工作</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">或住在</span><span lang=\"ZH-HK\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast; mso-fareast-language: ZH-HK;\">鬧區</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">的人來說，只可以選擇良好的隔音設備才可以營造到一個較好的睡眠空間。除了選用雙層隔音玻璃的窗戶之外，也可以使用一些具吸音效果的窗簾，也可以隔絕</span>10<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">～</span>20<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">％的外界噪音，而且窗簾的布料越厚，吸音的效果越好，這也是個不錯的選擇。</span><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">但有些人則需要有點聲音才能入睡，一般會選擇開着電視睡，但往往第二天總是覺得十分睏倦，如果真的如此不妨試用其他聲音作為「白噪音」（</span>white&ensp; noise<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">），例如冷氣機、電風扇等發出的聲音。由於這些聲音都是單調而固定，不像電視所發出的聲音那樣多變，在寂靜與外界聲音之間起到阻隔作用，減少電視突如其來的聲響令你醒來。</span><br /><br /><img style=\"font-family: 新細明體; float: left; margin: 1px 0.5 1px 0.5;\" src=\"/mas_studio/storage/image/20171216/5a34cc011ea61.jpg\" width=\"343\" height=\"186\" /><strong>5)<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;</span></strong><strong><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">保持溫暖舒適</span></strong><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">睡眠時身體的溫度會逐漸下降，所以在清晨臨睡醒前會降至最低，因此房間的溫度要令我們感到舒適，有些專家</span>25<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">℃</span>&nbsp;<span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">的室溫最容易入睡，不過每個人的感覺不同，不妨嘗試找尋自己最舒適的睡房溫度。</span><br /><br /><span lang=\"ZH-TW\" style=\"font-family: 新細明體; mso-ascii-font-family: Calibri; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: 新細明體; mso-fareast-theme-font: minor-fareast;\">希望這幾篇的資訊可以為大家打造出一個好眠空間每晚也可以發個好夢。</span></p>\r\n<p><span style=\"font-family: 新細明體;\"><br /></span><strong>&nbsp; &nbsp; &nbsp;</strong></p>\r\n</body>\r\n</html>', '[\"387\"]', '2', '1');
INSERT INTO `mg_z_column` VALUES ('2', '踢走失眠·打造好眠空間 (四)', '踢走失眠·打造好眠空間 (四)', '604期 ', '604期 ', '395', '1513699200', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;要打造一個好眠的空間需要考慮上期提及過的床褥及床上用品之外還有:</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;柔和的燈光有助睡眠</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;晚上的時分，眼睛接收到空間光線的轉變，大腦松果體會開始分泌褪黑激素，繼而帶來睡意，但若果在睡前接觸太亮的光線，會抑制褪黑激素的分泌，也容易間接導致失眠，所以在睡房內不宜有太過亮的燈光，一般我們也建議用上2700 &ndash; 3000 K色溫較暖色的燈光。當然大家也要避免在睡前玩手機，因為手機的藍光會使人更清醒之餘更會抑制褪黑激素的分泌，從而影響你的睡眠質素。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;但睡房不單只有睡床更有梳妝台、衣櫃、浴室等，所以為配合不同的用途建議於睡房內需要營造出不同氣氛的燈光情境，除了不同的天花燈如燈槽、天花燈等也需要配合台燈、地燈或者壁燈，有幫營造整體的氣氛。例如梳妝台上需要台燈或給女士化妝專用正面安裝的壁燈、床頭的天花位置不宜安裝床頭射燈，因為太刺眼的強光同樣使人更清醒，不妨考慮安裝壁燈、吊燈或台燈。另外燈光設計上建議加入光暗掣，便可按個人需要打造出不同的情景。最後若需要夜燈的話，建議安裝在低於床位置，這樣便不會影響睡眠。</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;窗簾的重要</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;燈光是影響睡眠的一大因素，除了設計好睡房內不同的燈光氣氛之餘，也要避免早上的天然光或戶外的燈光影響。一般也安裝二層式的窗簾及窗紗，窗簾具有全遮光的效果，而窗紗就可以在日間選擇性的讓陽光進入室內同時又可遮擋外界視線加強私隱，需要安裝二層式的窗簾及窗紗不用太多的空間，但若果空間條件不足或不喜愛這款布藝的窗簾，也可以考慮卷簾，但緊記需要在兩則安裝遮光條才可有效達到遮光效果。</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;睡房的主要作用是睡覺</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;如果希望晚上可以好好睡一覺的話，就要嚴格限制在床上的時間，白天時最好連床都不要碰即不可以午睡，只可管制在晚上才可以睡覺。而且要明白睡房的設計主要是供給睡覺的地方，避免作處理工作及討論事物之場所，也不是用來當作看電視及吃飯的地方。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;讓睡房回歸單純機能就是睡覺，有些人習慣在睡房看電視，甚至安放書台、遊戲器等設備，但你若真的希望好眠，便要避免在睡房內加入過多的設備。因為對失眠的人來說，如果又太常在床上做睡眠以外的事情，身體就會自然記憶：「在床上可以不用睡覺。」也間接造成輾轉難眠的原因。要不便在床尾/床則多放一張椅子，作為睡前閱讀、聽音樂或看電視等使用，以保留床與睡眠間最單純的連結。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img src=\"/mas_studio/storage/image/20171220/5a39bf6450896.jpg\" alt=\"\" width=\"193\" height=\"219\" />&nbsp;<img src=\"/mas_studio/storage/image/20171220/5a39bf63dc629.jpg\" alt=\"\" width=\"218\" height=\"219\" />&nbsp;<img src=\"/mas_studio/storage/image/20171220/5a39bf6401f09.jpg\" alt=\"\" width=\"143\" height=\"220\" />&nbsp;<img src=\"/mas_studio/storage/image/20171220/5a39bf63dc629.jpg\" alt=\"\" width=\"220\" height=\"223\" /></span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp;要打造一個好眠的空間需要考慮上期提及過的床褥及床上用品之外還有:</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;柔和的燈光有助睡眠</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;晚上的時分，眼睛接收到空間光線的轉變，大腦松果體會開始分泌褪黑激素，繼而帶來睡意，但若果在睡前接觸太亮的光線，會抑制褪黑激素的分泌，也容易間接導致失眠，所以在睡房內不宜有太過亮的燈光，一般我們也建議用上2700 &ndash; 3000 K色溫較暖色的燈光。當然大家也要避免在睡前玩手機，因為手機的藍光會使人更清醒之餘更會抑制褪黑激素的分泌，從而影響你的睡眠質素。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;但睡房不單只有睡床更有梳妝台、衣櫃、浴室等，所以為配合不同的用途建議於睡房內需要營造出不同氣氛的燈光情境，除了不同的天花燈如燈槽、天花燈等也需要配合台燈、地燈或者壁燈，有幫營造整體的氣氛。例如梳妝台上需要台燈或給女士化妝專用正面安裝的壁燈、床頭的天花位置不宜安裝床頭射燈，因為太刺眼的強光同樣使人更清醒，不妨考慮安裝壁燈、吊燈或台燈。另外燈光設計上建議加入光暗掣，便可按個人需要打造出不同的情景。最後若需要夜燈的話，建議安裝在低於床位置，這樣便不會影響睡眠。</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;窗簾的重要</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;燈光是影響睡眠的一大因素，除了設計好睡房內不同的燈光氣氛之餘，也要避免早上的天然光或戶外的燈光影響。一般也安裝二層式的窗簾及窗紗，窗簾具有全遮光的效果，而窗紗就可以在日間選擇性的讓陽光進入室內同時又可遮擋外界視線加強私隱，需要安裝二層式的窗簾及窗紗不用太多的空間，但若果空間條件不足或不喜愛這款布藝的窗簾，也可以考慮卷簾，但緊記需要在兩則安裝遮光條才可有效達到遮光效果。</span></span></p>\r\n<p class=\"MsoNormal\"><strong><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &middot;睡房的主要作用是睡覺</span></span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;如果希望晚上可以好好睡一覺的話，就要嚴格限制在床上的時間，白天時最好連床都不要碰即不可以午睡，只可管制在晚上才可以睡覺。而且要明白睡房的設計主要是供給睡覺的地方，避免作處理工作及討論事物之場所，也不是用來當作看電視及吃飯的地方。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体;\"><span style=\"font-size: 16px;\">&nbsp; &nbsp;讓睡房回歸單純機能就是睡覺，有些人習慣在睡房看電視，甚至安放書台、遊戲器等設備，但你若真的希望好眠，便要避免在睡房內加入過多的設備。因為對失眠的人來說，如果又太常在床上做睡眠以外的事情，身體就會自然記憶：「在床上可以不用睡覺。」也間接造成輾轉難眠的原因。要不便在床尾/床則多放一張椅子，作為睡前閱讀、聽音樂或看電視等使用，以保留床與睡眠間最單純的連結。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20171220/5a39bf6450896.jpg\" alt=\"\" width=\"193\" height=\"219\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20171220/5a39bf63dc629.jpg\" alt=\"\" width=\"218\" height=\"219\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20171220/5a39bf6401f09.jpg\" alt=\"\" width=\"143\" height=\"220\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20171220/5a39bf63dc629.jpg\" alt=\"\" width=\"220\" height=\"223\" /></p>\r\n</body>\r\n</html>', '[\"395\"]', '1', '1');
INSERT INTO `mg_z_column` VALUES ('5', '品味·茶室 (上)', '品味·茶室 (上)', '606期 ', '606期 ', '749', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span></p>\r\n<table style=\"height: 415px; width: 474px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 286px;\">\r\n<td style=\"width: 286px; height: 282px;\">\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"/mas_studio/storage/image/20180103/5a4c6d33e9784.jpg\" alt=\"\" width=\"260\" height=\"174\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"/mas_studio/storage/image/20180504/5aebfc450f1cb.jpg\" width=\"262\" height=\"174\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">　</span></span><span style=\"font-family: 宋体; font-size: 16px;\">　</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>品茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、泡茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，對不少人來說茶道好像多在中國</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、台灣、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>日本的地方較為多，但茶對我們來說一點也不陌生，甚至我們每天也會接觸到</span> ;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>例如與家人</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>朋友午餐時的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ldquo;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>飲茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&rdquo;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>一盅兩件，便已經品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>賞</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>到中國茶</span>;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>太</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>太們或是三五知己去酒店嘆的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Afternoon Tea <span>品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>賞</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>到西茶</span> ;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>即使連日常去的茶餐廳也會飲到奶茶或者檸檬茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。所以中茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、西</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>甚</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>或</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>日式的抹茶、玄米茶等也好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，對</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>我們各人來說一點也不</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>陌生，只是大家還未注意到真正茶道中的藝術</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、禮儀及賞茶時的美感之道</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，不過也有不少年輕一輩多注意了茶道</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">　</span></span><span style=\"font-family: 宋体; font-size: 16px;\">　</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>茶道源於中國，並且至少早在唐朝或更前，於南宋時期才傳到日本及朝鮮，之後才傳至西方</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>茶道是通過沏茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、賞</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>聞茶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>飲茶的過程中增進友誼</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>美心修德</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>學習禮法</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>領略傳統美德等等，也是一種和美儀式。主要透過</span> </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>賞</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>茶的過程能達至靜心</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>靜神，去除雜念等來陶冶情操。品茶這種高深的學問不可能只在這裡三言兩語簡單的道出，當然如何打造出具有意境的茶室及其當中的要素便沒有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>難度</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">茶室內的家具</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">　</span></span><span style=\"font-family: 宋体; font-size: 16px;\">　</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>何謂茶道</span>？</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>當中必有洗茶，沖泡，封壺，分杯，分壺，奉茶，聞香，品茗等，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>但也離不開桌子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，因此整個茶室內的主角是泡茶桌，也需要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>按</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>照它來規劃</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。正宗的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>泡茶桌一般由木製長台搭配長凳或者明式椅，但由於地方所限，相對也出現如茶几般的木台再配上矮身的木椅子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">空間裝飾及設計</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>　</span></span>　茶室的設計由於供品茶及修德之用，牆身飾面設計上一定不可過於花巧，並且多以自然物料為主</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。但</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">同時也需要配搭上裝飾物才可打造出品味的茶室，不少人選擇具悠遠歷史的藝術字畫</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">水墨畫作為裝飾，而且水墨畫能表現景色的磅礡或者日常的一隅風景，讓品茗空間表現上更具東方情懷。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>　</span></span>　除了掛件外也不妨考慮擺件，如植物、雕塑、銀器等收藏品，或者一</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">些</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">民間的工藝品及琴棋書畫也可。除了這些飾</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">外，也可考慮到一些較為實用如窗簾、靠墊、紗幔、屏風、竹簾等使整體空間更協調及舒適。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: Calibri;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体;\">意境</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、氣氛及燈具</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>　</span></span>　要打造出茶室當中的韻味除了牆身的設計及裝飾品外</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，還要透</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">過</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">燈光才可把當中的感覺、氣氛及意境帶出，一般茶室選用能營造出較強光暗對比的局部照明，才可增強整體空間的層次感，並且造出光與影在意境上的最好詮釋。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;</span></span></p>\r\n<table style=\"width: 100%; border-collapse: collapse; float: left;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 100%;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c6d33c9bfb.jpg\" alt=\"\" width=\"163\" height=\"218\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c6d35817c0.jpg\" width=\"331\" height=\"219\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><br /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>　</span></span>　另外</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">燈具也要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">小心選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，燈籠、宮燈都是東方空間不可或缺的造型元素，常見以竹材為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">支架</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，外層則以透光宣紙糊成的圓燈籠。可考慮不同位置如吊燈、壁燈、落地燈等等，燈具的組合到位會讓茶室熠熠生輝，也可為空間增添韻味。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;</p>\r\n', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;</span></p>\r\n<table style=\"height: 415px; width: 474px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 286px;\">\r\n<td style=\"width: 286px; height: 282px;\">\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"/mas_studio/storage/image/20180103/5a4c6d33e9784.jpg\" alt=\"\" width=\"260\" height=\"174\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"data:image/jpeg;base64,\" alt=\"\" width=\"262\" height=\"174\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;品茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、泡茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，對不少人來說茶道好像多在中國</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、台灣、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">日本的地方較為多，但茶對我們來說一點也不陌生，甚至我們每天也會接觸到&nbsp;;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">例如與家人/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">朋友午餐時的</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ldquo;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">飲茶</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&rdquo;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一盅兩件，便已經品</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">賞</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">到中國茶;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">太</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">太們或是三五知己去酒店嘆的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Afternoon Tea&nbsp;品</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">賞</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">到西茶&nbsp;;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">即使連日常去的茶餐廳也會飲到奶茶或者檸檬茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。所以中茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、西</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">甚</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">或</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">日式的抹茶、玄米茶等也好</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，對</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">我們各人來說一點也不</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">陌生，只是大家還未注意到真正茶道中的藝術</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、禮儀及賞茶時的美感之道</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，不過也有不少年輕一輩多注意了茶道</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;茶道源於中國，並且至少早在唐朝或更前，於南宋時期才傳到日本及朝鮮，之後才傳至西方</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。而</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">茶道是通過沏茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、賞</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">聞茶</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">飲茶的過程中增進友誼</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">美心修德</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">學習禮法</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">領略傳統美德等等，也是一種和美儀式。主要透過&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">賞</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">茶的過程能達至靜心</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">靜神，去除雜念等來陶冶情操。品茶這種高深的學問不可能只在這裡三言兩語簡單的道出，當然如何打造出具有意境的茶室及其當中的要素便沒有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">難度</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">茶室內的家具</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;何謂茶道？</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">當中必有洗茶，沖泡，封壺，分杯，分壺，奉茶，聞香，品茗等，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">但也離不開桌子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，因此整個茶室內的主角是泡茶桌，也需要</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">按</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">照它來規劃</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。正宗的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">泡茶桌一般由木製長台搭配長凳或者明式椅，但由於地方所限，相對也出現如茶几般的木台再配上矮身的木椅子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">空間裝飾及設計</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;茶室的設計由於供品茶及修德之用，牆身飾面設計上一定不可過於花巧，並且多以自然物料為主</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。但</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">同時也需要配搭上裝飾物才可打造出品味的茶室，不少人選擇具悠遠歷史的藝術字畫/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">水墨畫作為裝飾，而且水墨畫能表現景色的磅礡或者日常的一隅風景，讓品茗空間表現上更具東方情懷。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;除了掛件外也不妨考慮擺件，如植物、雕塑、銀器等收藏品，或者一</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">些</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">民間的工藝品及琴棋書畫也可。除了這些飾</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">品</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">外，也可考慮到一些較為實用如窗簾、靠墊、紗幔、屏風、竹簾等使整體空間更協調及舒適。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: Calibri;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span>意境</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、氣氛及燈具</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;要打造出茶室當中的韻味除了牆身的設計及裝飾品外</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，還要透</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">過</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">燈光才可把當中的感覺、氣氛及意境帶出，一般茶室選用能營造出較強光暗對比的局部照明，才可增強整體空間的層次感，並且造出光與影在意境上的最好詮釋。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;</span></p>\r\n<table style=\"width: 100%; border-collapse: collapse; float: left;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 100%;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c6d33c9bfb.jpg\" alt=\"\" width=\"163\" height=\"218\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c6d35817c0.jpg\" width=\"331\" height=\"219\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;另外</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">燈具也要</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">小心選擇</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，燈籠、宮燈都是東方空間不可或缺的造型元素，常見以竹材為</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">支架</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，外層則以透光宣紙糊成的圓燈籠。可考慮不同位置如吊燈、壁燈、落地燈等等，燈具的組合到位會讓茶室熠熠生輝，也可為空間增添韻味。</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</body>\r\n</html>', '[\"749\"]', '3', '1');
INSERT INTO `mg_z_column` VALUES ('6', '品味·茶室 (下)', '品味·茶室 (下)', '607期 ', '607期 ', '754', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; 上期說</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">過</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">如可打造出一個良好的整體氣氛</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，舒適的意境</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">又怎何缺少</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">最後的細節</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，便可營造出十全十美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的茶室;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><strong><span style=\"font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp; &nbsp; &nbsp;&middot;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶具及細節</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶席間的佈置是品茶時的基本要素，也是一種待客禮儀及尊重茶文化的元</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">素</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，令整個品茶的過程更完美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。再者打造出完美的裝飾再配上精美的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶具時即使沒有泡茶人就位的茶席，也可稱為茶席的「空間藝術」，所以茶席上的佈置是十分重要例如用席巾、竹蓆為底襯等。而且也要了解所有器具的用處才顯得對其尊重</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">置茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶則：由茶罐中取茶置入茶壺的用具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶匙：將茶葉由茶則撥入茶壺的器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶漏（鬥）：放於壺口上導茶入壺，防止茶葉散落壺外。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶荷：屬多功能器具，除兼有前三者作用外，還可視茶形、斷多寡、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">聞乾香。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶倉：分裝茶葉的小茶罐。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">理茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶夾：將茶渣從壺中、杯中夾出；洗杯時可夾杯防手被燙。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶匙：用以置茶、挖茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶針：用於疏通壺嘴，以免茶渣阻塞造成出水不暢。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶槳（簪）：撇去茶沫的用具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶刀：撬開普洱茶餅時的工具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶筒：茶筒是用來盛放茶針、茶匙、茶漏、茶則以及茶夾等的器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">分茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶海（茶盅、母杯、公道杯）：茶壺中的茶湯泡好後可倒入茶海，然</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">後依人數多寡平均分配；而人數少時則倒出茶水可避免因浸泡太久而產生苦澀味。茶海上放濾網可濾去倒茶時隨之流出的茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">品茗器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶杯（品茗杯）：用於品啜茶湯。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;聞香杯：藉以保留茶香用來嗅聞鑑別。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;杯托：承放茶杯的小托盤，可避免茶湯燙手，也起美觀作用。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">滌潔器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶盤：用以盛放茶杯或其他茶具的盤子。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶船（茶池、茶洗、壺承）：盛放茶壺的器具，也用於盛接溢水及淋 &nbsp;&nbsp;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">壺茶湯，是養壺的必須器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;渣方：用以盛裝茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">水方（茶盂、水盂）：用於盛接棄置茶水。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;滌方：用於放置用過後待洗的杯、盤。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶巾：主要用於乾壺，可將茶壺、茶海底部殘留的雜水擦乾；其次用於抹淨桌面水滴。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">配件</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;煮水器：種類繁多主要有炭爐（潮汕爐）<span style=\"font-family: Calibri;\">+</span>玉書碨、酒精爐<span style=\"font-family: Calibri;\">+</span>玻璃水壺、電熱水壺、電磁爐等。選用要點為茶具配套和諧、煮水無異味。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;壺墊：紡織品。用於隔開壺與茶船，避免因碰撞而發出響聲影響氣氛。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;蓋置：用來放置茶壺蓋、水壺蓋的小盤（一般以茶托代替）。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;奉茶盤：奉茶用的托盤。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶拂：置茶後用於拂去茶荷中的殘存茶末。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;溫度計：用來學習判斷水溫。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶巾盤：用以放置茶巾、茶拂、溫度計等。</span></p>\r\n<ul>\r\n<li class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">香爐：喝茶焚香可增茶趣。</span></li>\r\n</ul>\r\n<table style=\"height: 214px; width: 568px; border-collapse: collapse;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 165px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71beb9d72.jpg\" alt=\"\" width=\"155\" height=\"178\" /></td>\r\n<td style=\"width: 136px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71beef9a9.jpg\" alt=\"\" width=\"118\" height=\"88\" /><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71bed1113.jpg\" alt=\"\" width=\"117\" height=\"77\" /></td>\r\n<td style=\"width: 257px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71bf0f23f.jpg\" alt=\"\" width=\"100\" height=\"175\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span></p>\r\n', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; 上期說</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">過</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">如可打造出一個良好的整體氣氛</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，舒適的意境</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">又怎何缺少</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">最後的細節</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，便可營造出十全十美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的茶室;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><strong><span style=\"font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp; &nbsp; &nbsp;&middot;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶具及細節</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶席間的佈置是品茶時的基本要素，也是一種待客禮儀及尊重茶文化的元</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">素</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，令整個品茶的過程更完美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。再者打造出完美的裝飾再配上精美的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶具時即使沒有泡茶人就位的茶席，也可稱為茶席的「空間藝術」，所以茶席上的佈置是十分重要例如用席巾、竹蓆為底襯等。而且也要了解所有器具的用處才顯得對其尊重</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">置茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶則：由茶罐中取茶置入茶壺的用具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶匙：將茶葉由茶則撥入茶壺的器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶漏（鬥）：放於壺口上導茶入壺，防止茶葉散落壺外。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶荷：屬多功能器具，除兼有前三者作用外，還可視茶形、斷多寡、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">聞乾香。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶倉：分裝茶葉的小茶罐。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">理茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶夾：將茶渣從壺中、杯中夾出；洗杯時可夾杯防手被燙。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶匙：用以置茶、挖茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶針：用於疏通壺嘴，以免茶渣阻塞造成出水不暢。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶槳（簪）：撇去茶沫的用具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶刀：撬開普洱茶餅時的工具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">茶筒：茶筒是用來盛放茶針、茶匙、茶漏、茶則以及茶夾等的器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">分茶器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶海（茶盅、母杯、公道杯）：茶壺中的茶湯泡好後可倒入茶海，然</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">後依人數多寡平均分配；而人數少時則倒出茶水可避免因浸泡太久而產生苦澀味。茶海上放濾網可濾去倒茶時隨之流出的茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.5500pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">品茗器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶杯（品茗杯）：用於品啜茶湯。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;聞香杯：藉以保留茶香用來嗅聞鑑別。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;杯托：承放茶杯的小托盤，可避免茶湯燙手，也起美觀作用。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">滌潔器</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶盤：用以盛放茶杯或其他茶具的盤子。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶船（茶池、茶洗、壺承）：盛放茶壺的器具，也用於盛接溢水及淋 &nbsp;&nbsp;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">壺茶湯，是養壺的必須器具。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;渣方：用以盛裝茶渣。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">水方（茶盂、水盂）：用於盛接棄置茶水。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;滌方：用於放置用過後待洗的杯、盤。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶巾：主要用於乾壺，可將茶壺、茶海底部殘留的雜水擦乾；其次用於抹淨桌面水滴。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">配件</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;煮水器：種類繁多主要有炭爐（潮汕爐）<span style=\"font-family: Calibri;\">+</span>玉書碨、酒精爐<span style=\"font-family: Calibri;\">+</span>玻璃水壺、電熱水壺、電磁爐等。選用要點為茶具配套和諧、煮水無異味。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;壺墊：紡織品。用於隔開壺與茶船，避免因碰撞而發出響聲影響氣氛。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;蓋置：用來放置茶壺蓋、水壺蓋的小盤（一般以茶托代替）。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;奉茶盤：奉茶用的托盤。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶拂：置茶後用於拂去茶荷中的殘存茶末。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;溫度計：用來學習判斷水溫。</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">-&nbsp;茶巾盤：用以放置茶巾、茶拂、溫度計等。</span></p>\r\n<ul>\r\n<li class=\"MsoNormal\" style=\"margin-left: 42.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">香爐：喝茶焚香可增茶趣。</span></li>\r\n</ul>\r\n<table style=\"height: 214px; width: 568px; border-collapse: collapse;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 165px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71beb9d72.jpg\" alt=\"\" width=\"155\" height=\"178\" /></td>\r\n<td style=\"width: 136px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71beef9a9.jpg\" alt=\"\" width=\"118\" height=\"88\" /><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71bed1113.jpg\" alt=\"\" width=\"117\" height=\"77\" /></td>\r\n<td style=\"width: 257px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c71bf0f23f.jpg\" alt=\"\" width=\"100\" height=\"175\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span></p>\r\n', '[\"754\"]', '4', '1');
INSERT INTO `mg_z_column` VALUES ('7', '公主·皇子的世界 (上)', '公主·皇子的世界 (上)', '608期 ', '608期 ', '759', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">小公主</span>/<span style=\"font-family: 宋体;\">小皇子的世界 </span><span style=\"font-family: Calibri;\">(</span><span style=\"font-family: 宋体;\">一</span><span style=\"font-family: Calibri;\">)</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">迎接</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">新生</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">命</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的來</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">臨</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，故</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">然</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">是一件喜樂的事，但同</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">樣</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">對父</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">母</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">來說也是一件十分擔憂的事，媽媽自從得知</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">懷孕的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">第一天，父</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">母</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">除</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">了開心之外還有的是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">擔心，擔心他的健康，吃的、用的會否對胎兒有影響、每月的產檢、還</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">天天各色各樣的維他命</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">補充品等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。當孩子快要出生時還要為他準備衣</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">食</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、住、行。當然不可缺少的是設計出一個既溫馨又舒適的房間給孩子，打造出一個可健康成長的環境</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">設計前要考慮</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">初生的嬰兒最初</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">1-3</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">個月最好就是和媽媽睡</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">4-6</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">個月大才開始分房睡比較好一點</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。所以</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">添置傢俬的時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">候</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">一定要預留寶寶的成長空間，避免訂造太多固定的傢俱，多選擇具彈性的活動傢俱便好。傢俱</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">盡量選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">設計成圓滑的鈍角，以防孩子撞到尖銳的角而受傷。而家中原有的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">傢俱最好套上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">保護。所有的櫃</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">傢俱要固定於牆身，免得突然倒下</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">安放危險或較重物件的櫃子也要鎖好。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">另外嬰兒床擺放的位置十分重要，如果媽媽與孩子同房的話，嬰兒床當然要放在主人床旁邊，以便媽媽可經常與</span>BB<span style=\"font-family: 宋体;\">有目光交流對視及方便照顧。千萬不可放近窗戶</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">或櫃子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">旁構成階梯形，以免</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">攀爬時摔下來，床上不應放大娃娃或大玩具，</span> <span style=\"font-family: 宋体;\">以防寶貝會爬動時爬到玩具身上踩著它跌下床。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">嬰兒床也不要靠近窗或者在冷氣出口下，以免窗戶的冷風或冷氣直接的吹到孩子上，也要遠離陽光照射到的地方，以免強烈的太陽光刺激寶貝的眼睛。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">嬰兒床亦要遠離燈座和任何掛有懸垂線圈的物品，如窗簾、布幔，</span> <span style=\"font-family: 宋体;\">遠離電風扇、電熱器等家用電器等。不要在嬰兒床上堆疊衣物，更不要讓孩子能夠拿到任何塑料袋或塑料布，</span> <span style=\"font-family: 宋体;\">以防嬰兒舞動手臂時，</span> <span style=\"font-family: 宋体;\">將其蓋在臉上導致窒息。而且床的四周要留有一定的空間方便家人照顧。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">在購買嬰兒床時要選擇有堅固圍欄的，並且護欄的條子距離不可太大，以及床墊不要太小更不可與床邊的距離多於</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">2-3</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">cm ( </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">約</span>2-3<span style=\"font-family: 宋体;\">隻手指</span><span style=\"font-family: Calibri;\">)</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，避免孩子摔下床或頭部伸出護欄時被卡住，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">而且經常要檢查</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">護欄是否固定及扣緊，避免孩子轉身時擠開床欄發生墜床事件。同時也不要掛上太多</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">太</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">堅硬的玩具，免孩子撞傷，最好圍欄四面也有軟墊保護免得孩子碰傷。也不要購買太柔軟的床上用品，</span> <span style=\"font-family: 宋体;\">因為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">很容易把自己的臉埋入柔軟的枕頭、被子里造成窒息。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7433d8475.jpg\" alt=\"\" width=\"253\" height=\"244\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c74341c25c.jpg\" alt=\"\" width=\"195\" height=\"244\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c7433f330b.jpg\" alt=\"\" width=\"162\" height=\"244\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c743440528.jpg\" alt=\"\" width=\"162\" height=\"245\" /></span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">小公主</span>/<span style=\"font-family: 宋体;\">小皇子的世界&nbsp;</span><span style=\"font-family: Calibri;\">(</span><span style=\"font-family: 宋体;\">一</span><span style=\"font-family: Calibri;\">)</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">迎接</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">新生</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">命</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">的來</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">臨</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，故</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">然</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">是一件喜樂的事，但同</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">樣</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">對父</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">母</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">來說也是一件十分擔憂的事，媽媽自從得知</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">懷孕的</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">第一天，父</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">母</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">除</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">了開心之外還有的是</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">擔心，擔心他的健康，吃的、用的會否對胎兒有影響、每月的產檢、還</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">有</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">天天各色各樣的維他命</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">/</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">補充品等等</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">。當孩子快要出生時還要為他準備衣</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">食</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">、住、行。當然不可缺少的是設計出一個既溫馨又舒適的房間給孩子，打造出一個可健康成長的環境</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">設計前要考慮</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">初生的嬰兒最初</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">1-3</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">個月最好就是和媽媽睡</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">4-6</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">個月大才開始分房睡比較好一點</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">。所以</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">在</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">添置傢俬的時</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">候</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">一定要預留寶寶的成長空間，避免訂造太多固定的傢俱，多選擇具彈性的活動傢俱便好。傢俱</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">盡量選擇</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">/</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">設計成圓滑的鈍角，以防孩子撞到尖銳的角而受傷。而家中原有的</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">傢俱最好套上</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">保護。所有的櫃</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">/</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">傢俱要固定於牆身，免得突然倒下</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">安放危險或較重物件的櫃子也要鎖好。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">另外嬰兒床擺放的位置十分重要，如果媽媽與孩子同房的話，嬰兒床當然要放在主人床旁邊，以便媽媽可經常與</span>BB<span style=\"font-family: 宋体;\">有目光交流對視及方便照顧。千萬不可放近窗戶</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">或櫃子</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">旁構成階梯形，以免</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">孩子</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">攀爬時摔下來，床上不應放大娃娃或大玩具，</span>&nbsp;<span style=\"font-family: 宋体;\">以防寶貝會爬動時爬到玩具身上踩著它跌下床。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">嬰兒床也不要靠近窗或者在冷氣出口下，以免窗戶的冷風或冷氣直接的吹到孩子上，也要遠離陽光照射到的地方，以免強烈的太陽光刺激寶貝的眼睛。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">嬰兒床亦要遠離燈座和任何掛有懸垂線圈的物品，如窗簾、布幔，</span>&nbsp;<span style=\"font-family: 宋体;\">遠離電風扇、電熱器等家用電器等。不要在嬰兒床上堆疊衣物，更不要讓孩子能夠拿到任何塑料袋或塑料布，</span>&nbsp;<span style=\"font-family: 宋体;\">以防嬰兒舞動手臂時，</span>&nbsp;<span style=\"font-family: 宋体;\">將其蓋在臉上導致窒息。而且床的四周要留有一定的空間方便家人照顧。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">在購買嬰兒床時要選擇有堅固圍欄的，並且護欄的條子距離不可太大，以及床墊不要太小更不可與床邊的距離多於</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">2-3</span><span style=\"font-family: Calibri; font-size: 12pt;\">cm (&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">約</span>2-3<span style=\"font-family: 宋体;\">隻手指</span><span style=\"font-family: Calibri;\">)</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，避免孩子摔下床或頭部伸出護欄時被卡住，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">而且經常要檢查</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">護欄是否固定及扣緊，避免孩子轉身時擠開床欄發生墜床事件。同時也不要掛上太多</span></span><span style=\"font-family: 宋体; font-size: 12pt;\">/</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">太</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">堅硬的玩具，免孩子撞傷，最好圍欄四面也有軟墊保護免得孩子碰傷。也不要購買太柔軟的床上用品，</span>&nbsp;<span style=\"font-family: 宋体;\">因為</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">孩子</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">很容易把自己的臉埋入柔軟的枕頭、被子里造成窒息。</span></span></p>\r\n<p class=\"MsoNormal\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c7433d8475.jpg\" alt=\"\" width=\"253\" height=\"244\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c74341c25c.jpg\" alt=\"\" width=\"195\" height=\"244\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c7433f330b.jpg\" alt=\"\" width=\"162\" height=\"244\" /><span style=\"font-family: 宋体; font-size: 16px;\">&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c743440528.jpg\" alt=\"\" width=\"162\" height=\"245\" /></p>\r\n</body>\r\n</html>', '[\"759\"]', '5', '1');
INSERT INTO `mg_z_column` VALUES ('8', '公主·皇子的世界 (下)', '公主·皇子的世界 (下)', '609期 ', '609期 ', '760', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;上期說到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">嬰兒房的設計是為孩子出生而準備的禮物之一，但當中有不少要注意的事情，例如房間的傢俱設計及購買嬰兒床等等，這期繼續講解</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">房間的裝修需要簡單一點，因過於繁復的裝修會使房間顯得凌亂，讓孩子感覺不舒服。色彩應以淡雅為主，大紅大紫、純黑及純白色的裝修都會給寶貝帶來不舒服的感覺，並避免用太多的玻璃及鏡子，若家中原有玻璃門</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">牆身也最好加上防護膜。亦可考慮在天花油上一點顏色，因為嬰兒有不少時間也會看著天花的。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">地台飾面最好避免使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">石材而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">選用木地板，既容易清潔又較溫暖舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。倘若房間已是雲石或瓷磚為地台飾面的話</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，只好在地面鋪上地毯或塑膠製的地席，但一定要常清洗，以免造成蟎蟲或者細菌污染。當然地上的物件也要擺放好，不要留有太多雜物或在房間內設計台階。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;房間的燈光設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">以</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">柔和為主</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，最好選用燈槽或者壁燈，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">要避免燈光直接刺到眼睛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，如果不能改動的話只好選舉反射式的吊燈。不要讓嬰</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">兒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">躺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">臥</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">在嬰兒床時望到床的左右其中一邊有光</span>,</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">這會容易造成嬰</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">兒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">長大後其</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">一隻眼睛出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">現</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">斜視。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;同時房間內的空氣質數也十分重要，除了要多開窗戶讓房間的空氣流通之外，也應盡量避免眾多親朋好友在孩子初</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">生</span>1-2<span style=\"font-family: 宋体;\">個月</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">來探望，令室內空氣污染和細菌侵入。還要注意在裝修後要隔一段長時間才好讓孩子入住，裝修前要和設計師或施工的師父先說好要選用無</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;( </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">揮發性有機物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;)<span style=\"font-family: 宋体;\">的物料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，包括</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">油漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、傢俱、木材等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，但怎樣說也好不少傢俬在製造過程中也會用上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">含</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC<span style=\"font-family: 宋体;\">的物料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，而且上期也有提及因孩子長大得快，如睡床</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、書枱這些傢俬買活動傢俬可能更好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，所以孩子的房間最好也避免造太多傢俬及木材質的牆身飾面，不妨以木皮飾面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">膠板的牆身又或一張漂亮又色彩繽紛的牆紙可更合適用在孩子的房間。在裝修後也可請專業的公司到家中檢查空間</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">傢俱內是否含有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，再者他們還可以幫你清理家中的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;嬰兒房的溫度和濕度也要留意，溫度最好在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">22</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">℃<span style=\"font-family: Calibri;\">-2</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">5</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">℃之間，濕度應保持在<span style=\"font-family: Calibri;\">50%</span><span style=\"font-family: 宋体;\">左右，冬天時開暖氣，但不要忽略濕度的問題，可在房間內擺放加濕器或者最簡單的掛濕毛巾或放一柸水也總比什麼也不做好。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;<strong>另外也有以下的事項要留意</strong></span></span><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">:</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;所有窗戶需要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">安裝好圍欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">鎖</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，以防孩子日後四處亂</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">爬到窗台便危險。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;於房門上安裝一個響鈴</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，當</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">爬出門時聽到聲音，防止發生意外。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;同時門也要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">裝</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">防止大風</span>/<span style=\"font-family: 宋体;\">大人沒留神時把門大力</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">關上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">時傷到孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<table style=\"width: 529px; border-collapse: collapse; float: left; height: 187px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 570px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c767556d7b.jpg\" alt=\"\" width=\"121\" height=\"182\" /><img style=\"margin-right: 3px; margin-left: 3px;\" src=\"/mas_studio/storage/image/20180103/5a4c76756e979.jpg\" width=\"138\" height=\"183\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 3px; margin-left: 3px;\" src=\"/mas_studio/storage/image/20180103/5a4c7675a4cc5.jpg\" width=\"114\" height=\"182\" /><img style=\"font-family: 宋体; font-size: 12pt;\" src=\"/mas_studio/storage/image/20180103/5a4c767596b73.jpg\" alt=\"\" width=\"121\" height=\"182\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;電源線路要盡可能隱蔽，</span> <span style=\"font-family: 宋体;\">最好選用帶有插座罩的插座。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;希望這些資料可幫助大家為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">小公主</span>/<span style=\"font-family: 宋体;\">小皇子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">打造出一個又安全又舒適的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">世界</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span>&nbsp; &nbsp;<span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;</span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;上期說到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>嬰兒房的設計是為孩子出生而準備的禮物之一，但當中有不少要注意的事情，例如房間的傢俱設計及購買嬰兒床等等，這期繼續講解</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>房間的裝修需要簡單一點，因過於繁復的裝修會使房間顯得凌亂，讓孩子感覺不舒服。色彩應以淡雅為主，大紅大紫、純黑及純白色的裝修都會給寶貝帶來不舒服的感覺，並避免用太多的玻璃及鏡子，若家中原有玻璃門</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>牆身也最好加上防護膜。亦可考慮在天花油上一點顏色，因為嬰兒有不少時間也會看著天花的。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>地台飾面最好避免使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>石材而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>選用木地板，既容易清潔又較溫暖舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。倘若房間已是雲石或瓷磚為地台飾面的話</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，只好在地面鋪上地毯或塑膠製的地席，但一定要常清洗，以免造成蟎蟲或者細菌污染。當然地上的物件也要擺放好，不要留有太多雜物或在房間內設計台階。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;房間的燈光設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>以</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>柔和為主</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，最好選用燈槽或者壁燈，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>要避免燈光直接刺到眼睛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，如果不能改動的話只好選舉反射式的吊燈。不要讓嬰</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>兒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>躺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>臥</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>在嬰兒床時望到床的左右其中一邊有光</span>,</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>這會容易造成嬰</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>兒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>長大後其</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>一隻眼睛出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>現</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>斜視。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;同時房間內的空氣質數也十分重要，除了要多開窗戶讓房間的空氣流通之外，也應盡量避免眾多親朋好友在孩子初</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>生</span>1-2<span>個月</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>來探望，令室內空氣污染和細菌侵入。還要注意在裝修後要隔一段長時間才好讓孩子入住，裝修前要和設計師或施工的師父先說好要選用無</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;(&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>揮發性有機物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;)<span>的物料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，包括</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>油漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、傢俱、木材等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，但怎樣說也好不少傢俬在製造過程中也會用上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>含</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC<span>的物料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，而且上期也有提及因孩子長大得快，如睡床</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、書枱這些傢俬買活動傢俬可能更好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，所以孩子的房間最好也避免造太多傢俬及木材質的牆身飾面，不妨以木皮飾面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>膠板的牆身又或一張漂亮又色彩繽紛的牆紙可更合適用在孩子的房間。在裝修後也可請專業的公司到家中檢查空間</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>傢俱內是否含有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，再者他們還可以幫你清理家中的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;嬰兒房的溫度和濕度也要留意，溫度最好在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">22</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">℃<span style=\"font-family: Calibri;\">-2</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">5</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">℃之間，濕度應保持在<span style=\"font-family: Calibri;\">50%</span><span>左右，冬天時開暖氣，但不要忽略濕度的問題，可在房間內擺放加濕器或者最簡單的掛濕毛巾或放一柸水也總比什麼也不做好。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;<strong>另外也有以下的事項要留意</strong></span></span><strong><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">:</span></strong><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp;所有窗戶需要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>安裝好圍欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>鎖</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>，以防孩子日後四處亂</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>爬到窗台便危險。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp;於房門上安裝一個響鈴</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，當</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>爬出門時聽到聲音，防止發生意外。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;同時門也要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>裝</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>防止大風</span>/<span>大人沒留神時把門大力</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>關上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>時傷到孩子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n<table style=\"width: 529px; border-collapse: collapse; float: left; height: 187px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 570px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c767556d7b.jpg\" alt=\"\" width=\"121\" height=\"182\" /><img style=\"margin-right: 3px; margin-left: 3px;\" src=\"/mas_studio/storage/image/20180103/5a4c76756e979.jpg\" width=\"138\" height=\"183\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 3px; margin-left: 3px;\" src=\"/mas_studio/storage/image/20180103/5a4c7675a4cc5.jpg\" width=\"114\" height=\"182\" /><img style=\"font-family: 宋体; font-size: 12pt;\" src=\"/mas_studio/storage/image/20180103/5a4c767596b73.jpg\" alt=\"\" width=\"121\" height=\"182\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;電源線路要盡可能隱蔽，</span>&nbsp;<span>最好選用帶有插座罩的插座。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp;希望這些資料可幫助大家為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>小公主</span>/<span>小皇子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>打造出一個又安全又舒適的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>世界</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n</body>\r\n</html>', '[\"759\"]', '6', '1');
INSERT INTO `mg_z_column` VALUES ('9', '公主·王子的小天地', '公主·王子的小天地', '610期 ', '610期 ', '765', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;&nbsp;&nbsp;</span></span></p>\r\n<table style=\"width: 509px; border-collapse: collapse; float: right; height: 395px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 403px;\">\r\n<td style=\"width: 366px; height: 403px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c77c0b367c.jpg\" alt=\"\" width=\"181\" height=\"212\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77be54946.jpg\" alt=\"\" width=\"170\" height=\"210\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77c0dfa8c.jpg\" alt=\"\" width=\"177\" height=\"177\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77be688c1.jpg\" alt=\"\" width=\"178\" height=\"178\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;前兩期的文章提到如何為準備出生的小公主</span>/<span style=\"font-family: 宋体;\">小皇子打造出一間漂亮又安全的嬰兒房作為父母送給他</span><span style=\"font-family: Calibri;\">/</span><span style=\"font-family: 宋体;\">她的一份禮物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，但孩子成長的速度就像霎眼間，遠遠比你想像中快得多。轉眼又到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">3<span style=\"font-family: 宋体;\">歲</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，孩子開始上課</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、有自己的想法、有自己喜歡的玩具、顏色、公仔等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也是時候需要為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">他</span>/<span style=\"font-family: 宋体;\">她人生另一階段送祝福</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;3-6<span style=\"font-family: 宋体;\">歲左右的孩子開始活躍</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，更沒有任何自制能力，所以在選擇傢俬時要特別留意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，市面上也有不少專為孩童設計的傢俬如</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">枱</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、椅子、床、櫃等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">也是比較輕或由塑膠製造而角位大多圓鈍、弧型狀，同時也要注意製造的物料是否為無鉛無毒、</span>VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">等等。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;孩子也有自己喜歡的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">顏色、公仔等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">較</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">喜愛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">活潑、鮮豔的主色調，市面上有不少牆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">紙為這個年齡的孩子而設</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">計，色彩繽紛的顏色不但讓空間顯得豐富，也有刺激兒童視覺發展的作用。而色彩繽紛的牆紙</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">牆身顏色可配搭上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">純白色的傢俬，再加上一點點彩色的飾品作為點綴，不但可豐富整體空間又不令人覺得煩躁同時也帶來夢幻童話世界的感覺。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;由於孩子在學習發展中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，不妨在部份的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">牆身或櫃門飾面上選用黑板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、白玻璃或一些特製如白板般的牆紙</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，讓孩子可在牆身發揮想像力在牆身</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">創作出自己的作品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;倘若覺得更換牆紙或翻新牆身的油漆太麻煩，不妨考慮市</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">上較容易採購到的牆身貼紙，圖案活潑又可重複黏貼，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不但</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">為空間增添特色，同時也可一併配用牆身飾品，例如鏡子，對年幼的兒童來說房內擺置鏡子，可以讓孩子看著鏡子學著認識自我，有助自我概念的發展。但為了安全的問題及防止玻璃鏡面破裂而造成危險，在街上可購買到由塑膠製造的鏡子而不是玻璃造的，這點可是要留意。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;另外儲物櫃子可選用開放式的書櫃，配上不同顏色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、公仔圖案等的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">箱子、盒子，又可擺放不同的書本</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">、公仔及玩具作為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Dis</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">play</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。也可以在牆身安裝上層架及掛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">鈎</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，不但有效利用空間，又可為平淡而簡單的牆面增添不少色彩，層架另一個好處是在較高的位置，孩子無法隨便接觸到如把玩具放在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">上面更</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不可隨時想玩便玩，這樣一切的遊樂時間決策權就在父母的手中。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c77bc61340.jpg\" alt=\"\" width=\"283\" height=\"283\" />&nbsp; &nbsp;最後可考慮採用一些大自然作為佈置的元素，例如天空藍的牆身</span> (</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">藍色在色彩學上有穩定情緒的作用，適合正臨好動期的小男孩</span>)</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">或是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">綠色叢林風格寢具、葉子形狀的掛飾再配上些動物毛公仔等等，為孩子的房間打造出與眾不同的睡房，增加孩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的想像空間。</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;</span></span></p>\r\n<table style=\"width: 509px; border-collapse: collapse; float: right; height: 395px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 403px;\">\r\n<td style=\"width: 366px; height: 403px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c77c0b367c.jpg\" alt=\"\" width=\"181\" height=\"212\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77be54946.jpg\" alt=\"\" width=\"170\" height=\"210\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77c0dfa8c.jpg\" alt=\"\" width=\"177\" height=\"177\" /><img src=\"/mas_studio/storage/image/20180103/5a4c77be688c1.jpg\" alt=\"\" width=\"178\" height=\"178\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;前兩期的文章提到如何為準備出生的小公主</span>/<span>小皇子打造出一間漂亮又安全的嬰兒房作為父母送給他</span><span style=\"font-family: Calibri;\">/</span><span>她的一份禮物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，但孩子成長的速度就像霎眼間，遠遠比你想像中快得多。轉眼又到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">3<span>歲</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，孩子開始上課</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、有自己的想法、有自己喜歡的玩具、顏色、公仔等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，也是時候需要為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>他</span>/<span>她人生另一階段送祝福</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;3-6<span>歲左右的孩子開始活躍</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，更沒有任何自制能力，所以在選擇傢俬時要特別留意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，市面上也有不少專為孩童設計的傢俬如</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>枱</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、椅子、床、櫃等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>也是比較輕或由塑膠製造而角位大多圓鈍、弧型狀，同時也要注意製造的物料是否為無鉛無毒、</span>VOC</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>等等。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;孩子也有自己喜歡的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>顏色、公仔等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>較</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>喜愛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>活潑、鮮豔的主色調，市面上有不少牆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>紙為這個年齡的孩子而設</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>計，色彩繽紛的顏色不但讓空間顯得豐富，也有刺激兒童視覺發展的作用。而色彩繽紛的牆紙</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>牆身顏色可配搭上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>純白色的傢俬，再加上一點點彩色的飾品作為點綴，不但可豐富整體空間又不令人覺得煩躁同時也帶來夢幻童話世界的感覺。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;由於孩子在學習發展中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，不妨在部份的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>牆身或櫃門飾面上選用黑板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、白玻璃或一些特製如白板般的牆紙</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，讓孩子可在牆身發揮想像力在牆身</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>創作出自己的作品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;倘若覺得更換牆紙或翻新牆身的油漆太麻煩，不妨考慮市</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>上較容易採購到的牆身貼紙，圖案活潑又可重複黏貼，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>不但</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>為空間增添特色，同時也可一併配用牆身飾品，例如鏡子，對年幼的兒童來說房內擺置鏡子，可以讓孩子看著鏡子學著認識自我，有助自我概念的發展。但為了安全的問題及防止玻璃鏡面破裂而造成危險，在街上可購買到由塑膠製造的鏡子而不是玻璃造的，這點可是要留意。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;另外儲物櫃子可選用開放式的書櫃，配上不同顏色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、公仔圖案等的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>箱子、盒子，又可擺放不同的書本</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、公仔及玩具作為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Dis</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">play</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。也可以在牆身安裝上層架及掛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>鈎</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，不但有效利用空間，又可為平淡而簡單的牆面增添不少色彩，層架另一個好處是在較高的位置，孩子無法隨便接觸到如把玩具放在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>上面更</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>不可隨時想玩便玩，這樣一切的遊樂時間決策權就在父母的手中。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c77bc61340.jpg\" alt=\"\" width=\"283\" height=\"283\" />&nbsp; &nbsp;最後可考慮採用一些大自然作為佈置的元素，例如天空藍的牆身</span>&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>藍色在色彩學上有穩定情緒的作用，適合正臨好動期的小男孩</span>)</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>或是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>綠色叢林風格寢具、葉子形狀的掛飾再配上些動物毛公仔等等，為孩子的房間打造出與眾不同的睡房，增加孩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>子</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的想像空間。</span></span></p>\r\n<p><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"765\"]', '7', '1');
INSERT INTO `mg_z_column` VALUES ('10', 'Teenage', 'Teenage', '611期 ', '611期 ', '776', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"padding-left: 30px;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp;&nbsp;</span></p>\r\n<table style=\"width: 577px; border-collapse: collapse; float: right; height: 260px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 247px;\">\r\n<td style=\"width: 549px; height: 247px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7d5db0109.jpg\" alt=\"\" width=\"179\" height=\"238\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c7d59c9611.jpg\" width=\"159\" height=\"238\" /><img src=\"/mas_studio/storage/image/20180103/5a4c7d5dd8873.jpg\" alt=\"\" width=\"182\" height=\"238\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">前幾期的文章及提及在孩子出生前如何為寶貝打造出理想又安全的嬰兒房間及開始成長時合適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">3-6歲孩子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">小天地後</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，轉眼間孩子已開始入讀小學進入人生另一個的階段，作為父母又要為他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的成長所需而準備。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">從前小時候喜愛</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">色彩繽紛的牆紙/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">牆身顏色一一也因著孩子開始上學、看事物多了、與同學溝通多了、上網及念書的時間又多了，一一改變而且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">更</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">有著個性化的思想，過於活潑的鮮豔色調已不再適合他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的房間，需要更換上較溫暖、沉實一點的顏色，而衣櫃、書台、書櫃及床等等的傢俬尺寸也因為身體不停的長高而需要更換。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">牆身的飾面及顏色也要由小主人自行決定，怎樣說也是他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的房子，而且他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們開始學習</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">模仿大人，就讓他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們為自己作決定，若選擇的是較鮮</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">或花巧的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">顏色或牆紙，建議其他的牆身最好選用白色，可減少整體空間的壓迫感，可配上不同顏色的傢俬造出對比。</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">倘若選擇整個房間是較淺色調如淺米、淺粉、灰的顏色，傢俬最好也選擇白色較好</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">一點</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">另外不需要選用太花</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">巧及帶有圖案的牆身飾面/牆紙</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，因為他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們開始長大也同時擁有自己喜愛的相片、明星、運動、遊戲等等，可把一面牆身留空讓他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們掛上自己喜愛裝飾。又或者在牆身上安裝好掛勾讓孩子自行決定掛放衣物、配件或用收納袋收放各式小物，讓牆面當成一個展示空間，等於是給小女生練習佈置房間的機會。</span></p>\r\n<table style=\"height: 224px; width: 446px; border-collapse: collapse; float: left;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 170px;\">\r\n<td style=\"width: 442px; height: 170px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7d59e2fd6.jpg\" alt=\"\" width=\"211\" height=\"158\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c7d5daa675.jpg\" width=\"147\" height=\"158\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">部分的傢俬可考慮按大人的尺寸要求來訂造</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">購買，如床、衣櫃等等，但書台可考慮購買在市面上專為成長中孩子設</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">計可自己調較不同高度的書台及椅子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。另外因為開始上學書本也愈來愈多，書架、書櫃也有其存在必要性，不妨選用有設計感、具創意性及開放式的書架，讓孩子能置身更具想像力的空間同時除了放書本外也可</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Dis</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">play&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一些自己喜愛的玩具/公仔</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。而女孩子也會希望有自己夢想中的梳妝台，不妨書台連梳妝台合併，在牆身加上鏡子及台則加一些櫃子放一點首飾同時也可作書籍、雜物的儲物空間。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">假若要2個孩子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">share同一個房間，有時難免會對空間分配有不同意見，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">可考慮把牆身分開</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，利用不同的掛飾讓</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">個</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">孩子有自己的話事權</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，進而創造出不同的個人風格牆面。另外也可選用上下鋪床組節省空間，又可擺放兩張書桌、衣櫃等，讓孩子學習與兄弟姊妹</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">相處的時候也可同時擁有個人的空間</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"padding-left: 30px;\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp;&nbsp;</span></p>\r\n<table style=\"width: 577px; border-collapse: collapse; float: right; height: 260px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 247px;\">\r\n<td style=\"width: 549px; height: 247px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7d5db0109.jpg\" alt=\"\" width=\"179\" height=\"238\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c7d59c9611.jpg\" width=\"159\" height=\"238\" /><img src=\"/mas_studio/storage/image/20180103/5a4c7d5dd8873.jpg\" alt=\"\" width=\"182\" height=\"238\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">前幾期的文章及提及在孩子出生前如何為寶貝打造出理想又安全的嬰兒房間及開始成長時合適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">3-6歲孩子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">小天地後</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，轉眼間孩子已開始入讀小學進入人生另一個的階段，作為父母又要為他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的成長所需而準備。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">從前小時候喜愛</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">色彩繽紛的牆紙/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">牆身顏色一一也因著孩子開始上學、看事物多了、與同學溝通多了、上網及念書的時間又多了，一一改變而且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">更</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">有著個性化的思想，過於活潑的鮮豔色調已不再適合他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的房間，需要更換上較溫暖、沉實一點的顏色，而衣櫃、書台、書櫃及床等等的傢俬尺寸也因為身體不停的長高而需要更換。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">牆身的飾面及顏色也要由小主人自行決定，怎樣說也是他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們的房子，而且他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們開始學習</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">模仿大人，就讓他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們為自己作決定，若選擇的是較鮮</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">或花巧的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">顏色或牆紙，建議其他的牆身最好選用白色，可減少整體空間的壓迫感，可配上不同顏色的傢俬造出對比。</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">倘若選擇整個房間是較淺色調如淺米、淺粉、灰的顏色，傢俬最好也選擇白色較好</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">一點</span><span style=\"font-family: 宋体; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">另外不需要選用太花</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">巧及帶有圖案的牆身飾面/牆紙</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，因為他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們開始長大也同時擁有自己喜愛的相片、明星、運動、遊戲等等，可把一面牆身留空讓他</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">她們掛上自己喜愛裝飾。又或者在牆身上安裝好掛勾讓孩子自行決定掛放衣物、配件或用收納袋收放各式小物，讓牆面當成一個展示空間，等於是給小女生練習佈置房間的機會。</span></p>\r\n<table style=\"height: 224px; width: 446px; border-collapse: collapse; float: left;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 170px;\">\r\n<td style=\"width: 442px; height: 170px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7d59e2fd6.jpg\" alt=\"\" width=\"211\" height=\"158\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c7d5daa675.jpg\" width=\"147\" height=\"158\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">部分的傢俬可考慮按大人的尺寸要求來訂造</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">購買，如床、衣櫃等等，但書台可考慮購買在市面上專為成長中孩子設</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">計可自己調較不同高度的書台及椅子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。另外因為開始上學書本也愈來愈多，書架、書櫃也有其存在必要性，不妨選用有設計感、具創意性及開放式的書架，讓孩子能置身更具想像力的空間同時除了放書本外也可</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Dis</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">play&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一些自己喜愛的玩具/公仔</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。而女孩子也會希望有自己夢想中的梳妝台，不妨書台連梳妝台合併，在牆身加上鏡子及台則加一些櫃子放一點首飾同時也可作書籍、雜物的儲物空間。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">假若要2個孩子</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">share同一個房間，有時難免會對空間分配有不同意見，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">可考慮把牆身分開</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，利用不同的掛飾讓</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">2</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">個</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">孩子有自己的話事權</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，進而創造出不同的個人風格牆面。另外也可選用上下鋪床組節省空間，又可擺放兩張書桌、衣櫃等，讓孩子學習與兄弟姊妹</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">相處的時候也可同時擁有個人的空間</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"776\"]', '8', '1');
INSERT INTO `mg_z_column` VALUES ('11', '老友記居家安全(一)', '老友記居家安全(一)', '612期', '612期', '781', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 259px; border-collapse: collapse; float: right; height: 309px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 268px;\">\r\n<td style=\"width: 255px; height: 230px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7f2c318d9.jpg\" alt=\"\" width=\"242\" height=\"161\" /><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2b3564f.jpg\" alt=\"\" width=\"141\" height=\"94\" /><img style=\"margin-right: 2px; margin-left: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2b197ad.jpg\" width=\"94\" height=\"94\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;人生總會經歷成長並漸漸老去</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，那怕是自己或是父母，孩子出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">生你會為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">他</span>/<span style=\"font-family: 宋体;\">她精心設計嬰兒房，同樣你的父母也因著你的出生而高興，所以作為子女</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">又怎可以不回報</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">父母對你每天關心的愛，你是否也同樣的需要為他們老年準備一下，打造合適他們的安全舒適居所</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;在設計嬰兒</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">孩子房間的時間，我們會注意孩子安全，顏色配搭舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。同樣設計長者居所時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">我們也先要明白及理解他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的需要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，老友記隨著年齡增長行動已不如以往般敏捷，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">活動緩慢</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">同樣因為身體機能衰退，眼睛開始朦朧看不清</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、因為體力不足</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，坐下或起床時更需要利用其他物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">件</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">幫助支撐或借力</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">當然爬高爬低更不是一件易事，根據過往的數據顯示每年</span>100<span style=\"font-family: 宋体;\">個長者當中有</span><span style=\"font-family: Calibri;\">20-30</span><span style=\"font-family: 宋体;\">個因為意外跌倒，若果需要坐輪椅的話家中的空間設計更需要配合到輪椅活動，所以要在設計時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">考慮</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">防跌倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、防燙</span>/<span style=\"font-family: 宋体;\">燒傷、擺放物品的高度問題、選擇合適的傢俬、日常生活等各方面所需</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">才可以設計出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">理</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">想居所</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;由於</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記容易跌倒／絆倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，所以這方面要特別注意</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;地台的飾面</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">要選擇防滑度較高的瓷磚或者木地板，避免選用光面的瓷磚或雲石的物料，浴室位置更要注意或是加上防滑膠墊，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">避免用地布</span>/<span style=\"font-family: 宋体;\">地毯，並要時常保持清潔及乾爽，特別是積水</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">／皂液</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">或油積等，以防長者跣倒。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;地台要平</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">門檻不可過高，約太高長者容易絆倒，倘若真的沒法避免便要加上色彩鮮艷及防滑膠貼，讓老友記注意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">容易分</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">辨到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">高低級。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">足夠照明</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">需要保持室內光線充足，提醒老友記在晚上</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">半夜活動時必須要開燈，並在床頭的位置加裝床頭燈</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、夜明燈、走廊燈、地腳燈等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，或是替他們加裝感應系統</span> (</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Motion Sense )</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span style=\"font-family: 宋体;\">便不怕他們忘了開燈，避免於晚上因為看不清地上的雜物而絆倒，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">而且沿著床邊</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">走廊及往洗手間經過的路也要加上燈光避免長者摸黑活動而絆倒。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;保持地方整潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，走廊和通道要常常</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">保持暢通，避免有雜物阻塞。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\"><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2babd72.jpg\" alt=\"\" width=\"187\" height=\"193\" />於需要的地方加裝扶手</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">如果長者行動不便，應使用手杖或助行工具，減低跌倒機會</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。如床邊位置</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，便要加裝扶手和床欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、安全腳踏</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也可協助長者起床，避免起床時跌倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。而浴室內的座廁、企缸和洗手盤等位置同樣也要加裝扶手</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">以</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">免他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">以毛巾架借力。另外也不要用浴缸</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，最好改用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">企缸</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，避免長者攀爬出入浴缸時跌倒，在企缸內可放冲涼板或加置穩固的膠椅，以便長者更衣時使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。亦有些可以開門並設有扶手、坐位及防滑功能的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">浴缸，特別供老友記使用的，既安全又舒適，也是個不錯的選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\">&nbsp;</p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 259px; border-collapse: collapse; float: right; height: 309px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 268px;\">\r\n<td style=\"width: 255px; height: 230px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c7f2c318d9.jpg\" alt=\"\" width=\"242\" height=\"161\" /><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2b3564f.jpg\" alt=\"\" width=\"141\" height=\"94\" /><img style=\"margin-right: 2px; margin-left: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2b197ad.jpg\" width=\"94\" height=\"94\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;人生總會經歷成長並漸漸老去</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，那怕是自己或是父母，孩子出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>生你會為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>他</span>/<span>她精心設計嬰兒房，同樣你的父母也因著你的出生而高興，所以作為子女</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>又怎可以不回報</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>父母對你每天關心的愛，你是否也同樣的需要為他們老年準備一下，打造合適他們的安全舒適居所</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;在設計嬰兒</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>孩子房間的時間，我們會注意孩子安全，顏色配搭舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。同樣設計長者居所時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>我們也先要明白及理解他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的需要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，老友記隨著年齡增長行動已不如以往般敏捷，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>活動緩慢</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>同樣因為身體機能衰退，眼睛開始朦朧看不清</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、因為體力不足</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，坐下或起床時更需要利用其他物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>件</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>幫助支撐或借力</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>當然爬高爬低更不是一件易事，根據過往的數據顯示每年</span>100<span>個長者當中有</span><span style=\"font-family: Calibri;\">20-30</span><span>個因為意外跌倒，若果需要坐輪椅的話家中的空間設計更需要配合到輪椅活動，所以要在設計時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>考慮</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>防跌倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、防燙</span>/<span>燒傷、擺放物品的高度問題、選擇合適的傢俬、日常生活等各方面所需</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>才可以設計出</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>理</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>想居所</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;由於</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>老友記容易跌倒／絆倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，所以這方面要特別注意</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp;地台的飾面</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>要選擇防滑度較高的瓷磚或者木地板，避免選用光面的瓷磚或雲石的物料，浴室位置更要注意或是加上防滑膠墊，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>避免用地布</span>/<span>地毯，並要時常保持清潔及乾爽，特別是積水</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>／皂液</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>或油積等，以防長者跣倒。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;地台要平</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>門檻不可過高，約太高長者容易絆倒，倘若真的沒法避免便要加上色彩鮮艷及防滑膠貼，讓老友記注意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>容易分</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>辨到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>高低級。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>足夠照明</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>需要保持室內光線充足，提醒老友記在晚上</span>/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>半夜活動時必須要開燈，並在床頭的位置加裝床頭燈</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、夜明燈、走廊燈、地腳燈等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，或是替他們加裝感應系統</span>&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Motion Sense )</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;<span>便不怕他們忘了開燈，避免於晚上因為看不清地上的雜物而絆倒，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>而且沿著床邊</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>走廊及往洗手間經過的路也要加上燈光避免長者摸黑活動而絆倒。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp;保持地方整潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，走廊和通道要常常</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>保持暢通，避免有雜物阻塞。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c7f2babd72.jpg\" alt=\"\" width=\"187\" height=\"193\" />於需要的地方加裝扶手</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>如果長者行動不便，應使用手杖或助行工具，減低跌倒機會</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。如床邊位置</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，便要加裝扶手和床欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、安全腳踏</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，也可協助長者起床，避免起床時跌倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。而浴室內的座廁、企缸和洗手盤等位置同樣也要加裝扶手</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>以</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>免他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>以毛巾架借力。另外也不要用浴缸</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，最好改用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>企缸</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，避免長者攀爬出入浴缸時跌倒，在企缸內可放冲涼板或加置穩固的膠椅，以便長者更衣時使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。亦有些可以開門並設有扶手、坐位及防滑功能的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>浴缸，特別供老友記使用的，既安全又舒適，也是個不錯的選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。</span></span></p>\r\n<p><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"781\"]', '9', '1');
INSERT INTO `mg_z_column` VALUES ('12', '老友記居家安全(二)', '老友記居家安全(二)', '613期', '613期 ', '782', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 228px; border-collapse: collapse; float: right; height: 489px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 467px;\">\r\n<td style=\"width: 224px; height: 521px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c80e2838cd.jpg\" alt=\"\" width=\"212\" height=\"158\" /><img style=\"margin-bottom: 8px; margin-top: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c80e29c94c.png\" width=\"212\" height=\"165\" /><img src=\"/mas_studio/storage/image/20180103/5a4c80e3be4f6.jpg\" alt=\"\" width=\"213\" height=\"120\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; 作為父母你時刻也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">會</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">為孩子著想，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">我們的父母同樣</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">是為我們守住每一天</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，所以當他們</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">日</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">漸年老時，我們也必須為他們做點事，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">其一是打</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">造安全的家居設計好讓他們更安全</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。上期提及過</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">容</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">易跌倒</span>/<span style=\"font-family: 宋体;\">絆倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，所以在家居上地台的飾面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">照明</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">及加裝</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">扶手等地方要注意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，這一期我們繼續如</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">何</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">避免老友記發生意外</span>;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">防</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">燙</span>/<span style=\"font-family: 宋体;\">燒傷、擺放物品的高度問題、選擇合適的傢俬、日常生活健康等各方面所需</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; 不少</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記也喜愛收藏一些舊物品，甚至塑膠用具及塑膠袋，當然能把品物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">整潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">儲存起來是沒有問題</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，但倘若是亂放問題則可大了，特別在煮食爐附近不可放置易燃物品，如報紙</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">火水</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">石油氣罐或壓縮式噴劑</span> (<span style=\"font-family: 宋体;\">殺蟲劑</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">清潔噴霧等</span>)</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。冷天暖爐附近也不宜放置布料、衣物、雜物、沙發及床鋪</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，容易引致火警發生</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。也有些老友記會在家中燃點香燭</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，最好找一個特定的位置如神櫃，用上防火膠板等物料擺放的位置也要避免被風吹到，而且燃點香燭的位置不可靠近窗簾、紙張、易燃的傢俱等，以免發生火警</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。當然如吸煙的老友記更不可在床上吸煙</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，而且要確保煙蒂要徹底弄熄，才可丟入垃圾桶，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">若</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">他們願意</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">戒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">煙，免損健康更是最好不過</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">另外要讓老友記留意在使用暖爐時不可長開</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，最好用上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">時間制</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，同時在煮食</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">也該用鬧鐘提示長者熄火時間，以免在煮食途中老友記忘了關爐便外出或小睡</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">如果可以的話不妨更用電子煮食爐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，特別在滾瀉時會自己關上亦可設定時間</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">掣</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">煮食爐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">可自動關上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。另外也可安裝冷暖恆暖的冷氣</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，在浴室內則安裝浴室寶也達致暖氣的效果又能避免使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">暖爐的危險。說到電要確保房間有內有足夠的插座</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也要避免在單一插座上同時插上太多電器及加入太多接駁器等，以免電線短路而失火，如加上拖板也要捆好電線及拖板，貼近牆邊放好，以免絆倒長者</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。而且</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">要經常檢查電線和電器等有否破損，以防漏電或失火</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;&nbsp;</span></span><img style=\"font-family: 宋体; font-size: 16px; float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c80e36cb92.png\" alt=\"\" width=\"348\" height=\"237\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">除</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">了</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">因為安全的問題之外，也因為老友記行動問題更不可要他們擒高擒低，所以他們日常用品要放在伸手易取及固定的地方，需要時加上清楚的標籤，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">好</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">讓長者識別</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。也可幫助他們收拾及分類</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，定期丟掉不需使用的雜物，並將有用的東西整理放入箱或櫃內，存放物品時，將常用的物件放在櫃子的中格，以方便長者提取，不常用的物件可放在上格，較重的則放在下格就更安全</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 228px; border-collapse: collapse; float: right; height: 489px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 467px;\">\r\n<td style=\"width: 224px; height: 521px;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c80e2838cd.jpg\" alt=\"\" width=\"212\" height=\"158\" /><img style=\"margin-bottom: 8px; margin-top: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c80e29c94c.png\" width=\"212\" height=\"165\" /><img src=\"/mas_studio/storage/image/20180103/5a4c80e3be4f6.jpg\" alt=\"\" width=\"213\" height=\"120\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; 作為父母你時刻也</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">會</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">為孩子著想，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">我們的父母同樣</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">是為我們守住每一天</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，所以當他們</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">日</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">漸年老時，我們也必須為他們做點事，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">其一是打</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">造安全的家居設計好讓他們更安全</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。上期提及過</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">老友記</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">容</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">易跌倒/絆倒</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，所以在家居上地台的飾面</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">照明</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">及加裝</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">扶手等地方要注意</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，這一期我們繼續如</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">何</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">避免老友記發生意外;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">防</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">燙/燒傷、擺放物品的高度問題、選擇合適的傢俬、日常生活健康等各方面所需</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; 不少</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">老友記也喜愛收藏一些舊物品，甚至塑膠用具及塑膠袋，當然能把品物</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">整潔</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">儲存起來是沒有問題</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，但倘若是亂放問題則可大了，特別在煮食爐附近不可放置易燃物品，如報紙</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">火水</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">石油氣罐或壓縮式噴劑(殺蟲劑</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">清潔噴霧等)</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。冷天暖爐附近也不宜放置布料、衣物、雜物、沙發及床鋪</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，容易引致火警發生</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。也有些老友記會在家中燃點香燭</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，最好找一個特定的位置如神櫃，用上防火膠板等物料擺放的位置也要避免被風吹到，而且燃點香燭的位置不可靠近窗簾、紙張、易燃的傢俱等，以免發生火警</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。當然如吸煙的老友記更不可在床上吸煙</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，而且要確保煙蒂要徹底弄熄，才可丟入垃圾桶，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">若</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">他們願意</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">戒</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">煙，免損健康更是最好不過</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">另外要讓老友記留意在使用暖爐時不可長開</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，最好用上</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">時間制</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，同時在煮食</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">時</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也該用鬧鐘提示長者熄火時間，以免在煮食途中老友記忘了關爐便外出或小睡</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">如果可以的話不妨更用電子煮食爐</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，特別在滾瀉時會自己關上亦可設定時間</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">掣</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">煮食爐</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">可自動關上</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。另外也可安裝冷暖恆暖的冷氣</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，在浴室內則安裝浴室寶也達致暖氣的效果又能避免使用</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">暖爐的危險。說到電要確保房間有內有足夠的插座</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，也要避免在單一插座上同時插上太多電器及加入太多接駁器等，以免電線短路而失火，如加上拖板也要捆好電線及拖板，貼近牆邊放好，以免絆倒長者</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。而且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">要經常檢查電線和電器等有否破損，以防漏電或失火</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;&nbsp;</span><img style=\"font-family: 宋体; font-size: 16px; float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c80e36cb92.png\" alt=\"\" width=\"348\" height=\"237\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">除</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">了</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">因為安全的問題之外，也因為老友記行動問題更不可要他們擒高擒低，所以他們日常用品要放在伸手易取及固定的地方，需要時加上清楚的標籤，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">好</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">讓長者識別</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。也可幫助他們收拾及分類</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，定期丟掉不需使用的雜物，並將有用的東西整理放入箱或櫃內，存放物品時，將常用的物件放在櫃子的中格，以方便長者提取，不常用的物件可放在上格，較重的則放在下格就更安全</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n', '[\"782\"]', '10', '1');
INSERT INTO `mg_z_column` VALUES ('13', '老友記居家安全(三)', '老友記居家安全(三)', '614期', '614期', '787', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;前兩期也提及過應為漸漸年老的父母盡些孝道，打造一個安全的家居好讓他們過得更舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。之前所提及要注意的地方有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">防</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">跌倒／絆倒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">包括地台飾面</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">注意的地方</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">照明的選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、需要加裝</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">扶手的位置</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">防</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">燙</span>/<span style=\"font-family: 宋体;\">燒傷及擺放物品的高度問題等等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，這一期我們繼續如何</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">選擇合適的傢俬、日常生活健康等要注意的地方好讓老友記住得更</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;於選擇傢俬時，儲物櫃不能過高或過低，最好櫃面及腰方便長者拿取物件，不必因常彎腰取物而扭傷腰骨</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。衣物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">常用的品物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">也不應放置高處，避免長者攀高時而跌倒。若因為地方不夠需要把物品放到高處的話</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，可使用晾衣棒輔助拿取高處的衣物，並且使用一張穩固防滑</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">矮梯或梯架來協助取高處的物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">件</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，但盡可能也由子女協助或安裝有電動升降的櫃子，使空間更好用又減少意外的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">發生</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">電動</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">升降式的晾衣架</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，最低可調較至腰間位置，在杆上掛好衣物後，再輕按手掣將晾衣架升回天花上，對行動不便的長者來說，高舉雙手晾衫實屬生活中經常遇到的難題。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">另外可選擇圓角枱或加裝防撞墊的傢俬</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">避免不小心時撞傷。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; 利器及危險的物品也要放好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，提醒</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不要隨意把利器放在枱面，廚房內也要有固定位置安放利刀等物品</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。浴室和廚房盡量使用塑膠容器，避免使用玻璃器皿時不小心跌破而弄傷。藥物也要擺放好並分好種類，在當眼位置註明藥物的種類</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也不要放在同一藥瓶中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，避免吃錯藥</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">吃漏藥。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">除了傢俱的高度之外</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">在裝修時造插座</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、燈制開關、平安鐘等也要在高一點的位置</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，避免長者需要彎腰使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。電話及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">平安鐘要放於當眼的地方</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，並選用顏色鮮明，按鈕特大的款式，方便長者使用，並要定期檢查平安鐘正常運作</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。坐廁及洗手盆高度也要適中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，方便長者起坐，避免導致腳軟而跌倒，特別是坐輪椅的老友記更要有足夠的輪椅活動空間及扶手幫助，另外也可考慮電子的座廁，有暖廁板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、自動拿起</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">廁板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、沖洗功能及電動按制沖水等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也有可移動的洗手盆，這些對</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記來說也有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">幫助</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; 也不要安裝太多或重型的門鎖</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，當萬一意外發生時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">老友記</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">可迅速離開</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">方便救援人員進入屋內</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。窗戶最好安裝上穩固又可以活動並可上鎖的窗花，避免長者失足墮樓。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; 家居上我們可以花更多的錢加入不同的設計好讓父母在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">生活上更安全及舒適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，但再好的居所也需要家人心理上的安撫及照顧，記得不單單只花錢更要花多些時間陪陪家人</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836783e5a.jpg\" alt=\"\" width=\"254\" height=\"170\" /><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836703570.jpg\" alt=\"\" width=\"96\" height=\"170\" /><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836892e7e.jpg\" alt=\"\" width=\"171\" height=\"171\" /><img src=\"/mas_studio/storage/image/20180103/5a4c83684b915.jpg\" alt=\"\" width=\"141\" height=\"173\" /></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;前兩期也提及過應為漸漸年老的父母盡些孝道，打造一個安全的家居好讓他們過得更舒適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。之前所提及要注意的地方有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">防</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">跌倒／絆倒</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">包括地台飾面</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">注意的地方</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">照明的選擇</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、需要加裝</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">扶手的位置</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">防</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">燙/燒傷及擺放物品的高度問題等等</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，這一期我們繼續如何</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">選擇合適的傢俬、日常生活健康等要注意的地方好讓老友記住得更</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">舒適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;於選擇傢俬時，儲物櫃不能過高或過低，最好櫃面及腰方便長者拿取物件，不必因常彎腰取物而扭傷腰骨</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。衣物</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">常用的品物</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">也不應放置高處，避免長者攀高時而跌倒。若因為地方不夠需要把物品放到高處的話</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，可使用晾衣棒輔助拿取高處的衣物，並且使用一張穩固防滑</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">矮梯或梯架來協助取高處的物</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">件</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，但盡可能也由子女協助或安裝有電動升降的櫃子，使空間更好用又減少意外的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">發生</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">電動</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">升降式的晾衣架</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，最低可調較至腰間位置，在杆上掛好衣物後，再輕按手掣將晾衣架升回天花上，對行動不便的長者來說，高舉雙手晾衫實屬生活中經常遇到的難題。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">另外可選擇圓角枱或加裝防撞墊的傢俬</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">避免不小心時撞傷。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp; 利器及危險的物品也要放好</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，提醒</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">老友記</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">不要隨意把利器放在枱面，廚房內也要有固定位置安放利刀等物品</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。浴室和廚房盡量使用塑膠容器，避免使用玻璃器皿時不小心跌破而弄傷。藥物也要擺放好並分好種類，在當眼位置註明藥物的種類</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，也不要放在同一藥瓶中</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，避免吃錯藥</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">吃漏藥。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">除了傢俱的高度之外</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">在裝修時造插座</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、燈制開關、平安鐘等也要在高一點的位置</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，避免長者需要彎腰使用</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。電話及</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">平安鐘要放於當眼的地方</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，並選用顏色鮮明，按鈕特大的款式，方便長者使用，並要定期檢查平安鐘正常運作</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。坐廁及洗手盆高度也要適中</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，方便長者起坐，避免導致腳軟而跌倒，特別是坐輪椅的老友記更要有足夠的輪椅活動空間及扶手幫助，另外也可考慮電子的座廁，有暖廁板</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、自動拿起</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">廁板</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、沖洗功能及電動按制沖水等</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，也有可移動的洗手盆，這些對</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">老友記來說也有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">幫助</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;&nbsp;也不要安裝太多或重型的門鎖</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，當萬一意外發生時</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">老友記</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">亦</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">可迅速離開</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">方便救援人員進入屋內</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。窗戶最好安裝上穩固又可以活動並可上鎖的窗花，避免長者失足墮樓。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;&nbsp;家居上我們可以花更多的錢加入不同的設計好讓父母在</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">生活上更安全及舒適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，但再好的居所也需要家人心理上的安撫及照顧，記得不單單只花錢更要花多些時間陪陪家人</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836783e5a.jpg\" alt=\"\" width=\"254\" height=\"170\" /><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836703570.jpg\" alt=\"\" width=\"96\" height=\"170\" /><img style=\"margin-right: 2px;\" src=\"/mas_studio/storage/image/20180103/5a4c836892e7e.jpg\" alt=\"\" width=\"171\" height=\"171\" /><img src=\"/mas_studio/storage/image/20180103/5a4c83684b915.jpg\" alt=\"\" width=\"141\" height=\"173\" /></p>\r\n</body>\r\n</html>', '[\"787\"]', '11', '1');
INSERT INTO `mg_z_column` VALUES ('14', '綠色·居所', '綠色·居所', '615期', '615期', '792', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;&nbsp;</span></span></p>\r\n<table style=\"height: 239px; width: 598px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 233px;\">\r\n<td style=\"width: 594px; height: 233px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c856b26792.jpg\" alt=\"\" width=\"172\" height=\"232\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 6px; margin-left: 6px;\" src=\"/mas_studio/storage/image/20180103/5a4c856b5c282.jpg\" width=\"189\" height=\"232\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8569afc54.jpg\" alt=\"\" width=\"166\" height=\"232\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">&nbsp; &nbsp; &nbsp; &nbsp; 香港，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">在這個繁忙又緊張、節奏急促的城市裡生活，常常喘不過氣，總希望在忙裡偷閒逃離這個城市，溜到大自然去，那怕是陽光與海灘或滿是綠色的叢林好好享受一下。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">忙碌的工作</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">不是說</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">想</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">放假就放假，為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">了</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">望梅止渴不妨把這種大自然元素帶回家中，打造出一個悠然自在的家居環境，好讓</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">每天忙碌的生活中得到一到點放鬆。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">綠色自然家居不</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">只</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">要打造出讓人放鬆的自然感覺，同時要做到真正的綠色就是加入環保的元素才可叫做真正的綠色居所。所以在選擇物料方面也要符合「天然美」的原則</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">可持續發展的物料可符合環保的要求。例如：原木材、竹、石材、籐器等等，這些物料不但符合大自然的原則，當中更印記著它們自然</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">風霜</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">紋理，散發著樸實、原始、自然的味道，又能營造出休閒放鬆的效果。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Trebuchet MS\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">雖說要營造出渡假般的感覺但怎樣說也是家居設計又怎可缺少溫暖感，所以地台的飾面可考慮選用木地板、竹地板、英泥沙地台、石材等。木地板要選複合木地板，由於珍貴、漂亮的木材太多人選用，而且個別的木材生長周期長，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">故此</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">供不應求，而複合木地板的好處是只有面層幾</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">實木木材，而低層則用上生長周期較短的木材來取代，這樣便可減低對個別木材因供應量大而過度砍伐。而竹地板可營造出溫暖感之餘，本身也是生長周期短的環保物料。石材或板岩經過大自然多年的洗禮才</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">型</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">成，當中的斑剝痕跡亦是其他物料難以取代的，而英泥沙地台則可造出自然又簡約的味道。在選用任何物料時盡可能減少繁複的後期加工，盡量保留材質的天然味道、體態、質感，這樣才可合乎自然美。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">牆身裝飾反</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">清淡些較好，如油漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: PMingLiU;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">淺色的特色油漆或簡約的牆紙也可。千萬不要選用過於花巧的飾面，這樣反而讓人覺得凌亂及煩躁。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">此外</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">不妨部份的牆身也用上木材，木材</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">除</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">可給予人一種回歸山林的感</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">覺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">之外，當看見木材獨有的年輪及其天然的顏色，都可帶給人舒適及溫度感。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">傢俬的選擇除了木材外，籐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">製</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">傢俬</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">也是個不錯的選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">，而且十分普遍用於亞熱帶的國家，而籐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">製</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">傢俬給人質樸、自然的感覺，完全符合自然綠居家風格。配上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">編</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">織</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">布</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">的飾品或是傢俬也有助營造出渡假放鬆的感覺，例如亞麻布色彩天然又涼爽，更帶出自然的味道。</span></span></p>\r\n<table style=\"width: 502px; border-collapse: collapse; float: left; height: 149px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 366px;\"><img style=\"color: #222222; font-family: \'Times New Roman\'; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c856a52c0c.jpg\" alt=\"\" width=\"184\" height=\"155\" /><img style=\"color: #222222; font-family: \'Times New Roman\'; font-size: 16px; margin-right: 4px; margin-left: 4px;\" src=\"/mas_studio/storage/image/20180103/5a4c8569c7772.jpg\" width=\"167\" height=\"155\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;說是「綠色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Trebuchet MS\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">居所」當然少不了自然綠</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">的環境</span> -</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">綠色植</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">，除了直接把盆栽擺放在室內之餘，也可考慮市面上一些植物牆的設計或是盆栽畫等，不妨加入這些元素打造出獨有的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Feature wall</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">。可以增加與大自然產生連結，同時也有助室內的創造高氧量及淨化空氣的效果。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">&nbsp;</p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: Times New Roman;\">&nbsp; &nbsp;&nbsp;</span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp;&nbsp;</span></span></p>\r\n<table style=\"height: 239px; width: 598px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 233px;\">\r\n<td style=\"width: 594px; height: 233px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c856b26792.jpg\" alt=\"\" width=\"172\" height=\"232\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 6px; margin-left: 6px;\" src=\"/mas_studio/storage/image/20180103/5a4c856b5c282.jpg\" width=\"189\" height=\"232\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8569afc54.jpg\" alt=\"\" width=\"166\" height=\"232\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; 香港，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>在這個繁忙又緊張、節奏急促的城市裡生活，常常喘不過氣，總希望在忙裡偷閒逃離這個城市，溜到大自然去，那怕是陽光與海灘或滿是綠色的叢林好好享受一下。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>忙碌的工作</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>中</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>不是說</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>想</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>放假就放假，為</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>了</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>望梅止渴不妨把這種大自然元素帶回家中，打造出一個悠然自在的家居環境，好讓</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>在</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>每天忙碌的生活中得到一到點放鬆。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>綠色自然家居不</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>只</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>要打造出讓人放鬆的自然感覺，同時要做到真正的綠色就是加入環保的元素才可叫做真正的綠色居所。所以在選擇物料方面也要符合「天然美」的原則</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>可持續發展的物料可符合環保的要求。例如：原木材、竹、石材、籐器等等，這些物料不但符合大自然的原則，當中更印記著它們自然</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>風霜</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>紋理，散發著樸實、原始、自然的味道，又能營造出休閒放鬆的效果。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Trebuchet MS\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>雖說要營造出渡假般的感覺但怎樣說也是家居設計又怎可缺少溫暖感，所以地台的飾面可考慮選用木地板、竹地板、英泥沙地台、石材等。木地板要選複合木地板，由於珍貴、漂亮的木材太多人選用，而且個別的木材生長周期長，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>故此</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>供不應求，而複合木地板的好處是只有面層幾</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>實木木材，而低層則用上生長周期較短的木材來取代，這樣便可減低對個別木材因供應量大而過度砍伐。而竹地板可營造出溫暖感之餘，本身也是生長周期短的環保物料。石材或板岩經過大自然多年的洗禮才</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>型</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>成，當中的斑剝痕跡亦是其他物料難以取代的，而英泥沙地台則可造出自然又簡約的味道。在選用任何物料時盡可能減少繁複的後期加工，盡量保留材質的天然味道、體態、質感，這樣才可合乎自然美。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>牆身裝飾反</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>清淡些較好，如油漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>淺色的特色油漆或簡約的牆紙也可。千萬不要選用過於花巧的飾面，這樣反而讓人覺得凌亂及煩躁。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>此外</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>不妨部份的牆身也用上木材，木材</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>除</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>可給予人一種回歸山林的感</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>覺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>之外，當看見木材獨有的年輪及其天然的顏色，都可帶給人舒適及溫度感。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; text-indent: 24pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>傢俬的選擇除了木材外，籐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>製</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>傢俬</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>也是個不錯的選擇</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>，而且十分普遍用於亞熱帶的國家，而籐</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>製</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>傢俬給人質樸、自然的感覺，完全符合自然綠居家風格。配上</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>編</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>織</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>布</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>的飾品或是傢俬也有助營造出渡假放鬆的感覺，例如亞麻布色彩天然又涼爽，更帶出自然的味道。</span></span></p>\r\n<table style=\"width: 502px; border-collapse: collapse; float: left; height: 149px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 366px;\"><img style=\"color: #222222; font-family: \'Times New Roman\'; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c856a52c0c.jpg\" alt=\"\" width=\"184\" height=\"155\" /><img style=\"color: #222222; font-family: \'Times New Roman\'; font-size: 16px; margin-right: 4px; margin-left: 4px;\" src=\"/mas_studio/storage/image/20180103/5a4c8569c7772.jpg\" width=\"167\" height=\"155\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;說是「綠色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Trebuchet MS\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>居所」當然少不了自然綠</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>色</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>的環境</span>&nbsp;-</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>綠色植</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>物</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>，除了直接把盆栽擺放在室內之餘，也可考慮市面上一些植物牆的設計或是盆栽畫等，不妨加入這些元素打造出獨有的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Feature wall</span><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>。可以增加與大自然產生連結，同時也有助室內的創造高氧量及淨化空氣的效果。</span></span></p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">&nbsp;</p>\r\n<p class=\"p\" style=\"margin-top: 0pt; margin-bottom: 0pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"mso-spacerun: \'yes\'; font-family: \'Times New Roman\'; mso-bidi-font-family: \'Microsoft JhengHei\'; color: #222222; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span>&nbsp; &nbsp;&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"792\"]', '12', '1');
INSERT INTO `mg_z_column` VALUES ('15', '客廳·影音視聽空間 (一)', '客廳·影音視聽空間 (一)', '616期', '616期', '802', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p>&nbsp;</p>\r\n<table style=\"height: 409px; width: 334px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 423px;\">\r\n<td style=\"width: 326px; height: 339px;\">\r\n<table style=\"width: 360px; border-collapse: collapse; float: right; height: 343px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 419px;\">\r\n<td style=\"width: 334px; height: 351px;\"><img style=\"font-family: 宋体; font-size: 16px; margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874b81a58.jpg\" width=\"155\" height=\"233\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874bd31b3.jpg\" width=\"175\" height=\"233\" /><img style=\"margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874b9a3a7.jpg\" width=\"329\" height=\"160\" /><br /><br /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;香港地方有限，並不是每個家庭也可以擁有獨立的私人影院，只能把客廳與私人影院合二為一，雖然因為空間問題有所限制而不可打造出一個完美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">獨立的私人影院，但要造出一個優質的視聽客廳也需要注意些事項，首先在設計前要先考慮好器材、線的接駁及材料、器材擺放的角度及位置、牆身的物料及吸音問題等，我們逐點說解一下:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">裝修前要選定好器材，你需要的是一個家庭影院還是只聽純音樂的兩聲道系統，大家要明白兩者之間的系統是有所不同的，家庭影院的系統就是一套「迷你電影院」，於座位的四周圍設置多支喇叭、再利用環繞音效處理讓聲響從不同位置的喇叭以不同的音量發出，就能讓觀賞者感受如身歷其境的效果。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;簡單一點就是平常說的5.1、<span style=\"font-family: Calibri;\">7.1</span>，而當中的<span style=\"font-family: Calibri;\">5</span>及<span style=\"font-family: Calibri;\">7</span>是代表著喇叭的數量，點後的<span style=\"font-family: Calibri;\">1</span>字是代表著重低音喇叭<span style=\"font-family: Calibri;\">(</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;subwoofer)</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的數量。當中包括:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;中置&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Center</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">為人聲、主要音樂及中間方向音效的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">發聲位置</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，所有主要的聲音都由這裡發出。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">主喇叭&nbsp;/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">前置&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;L</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、R)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">來自前左及前右的聲音，營造出整個音場的氣勢、音樂及音效。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;重低音&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">subwoofer) &ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">發出極低頻的聲響，在觀看電影、音樂會時更震撼，若果空間很大，而一支重低音喇叭不足夠提供低音的震撼感，便需要兩支或以上的重低音。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;環繞喇叭&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;SL</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、SR)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">來自左右環繞的音效，令音場環繞及空間感更完整。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;後置喇叭&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">SBL、<span style=\"font-family: Calibri;\">SBR)</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;&ndash;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;是7.1聲道增加的喇叭，來自後左及後右的聲音，當然越多喇叭也就能營造的聲音效果包圍感就越好。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">家庭影院系統還要配上藍光播放機、AV擴音機&nbsp;<span style=\"font-family: Calibri;\">/</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">環繞擴音機&nbsp;(Amplifier)&nbsp;、電視、投影機、銀幕等。而純音樂的兩聲道系統配上的器材是<span style=\"font-family: Calibri;\">player (CD</span>機<span style=\"font-family: Calibri;\">/</span>黑膠唱片、或是存放&nbsp;<span style=\"font-family: Calibri;\">MP3&nbsp;</span>等數位音樂檔案的電腦等<span style=\"font-family: Calibri;\">)&nbsp;</span>、前級擴音機</span><span style=\"font-family: Calibri;\">/&nbsp;</span><span style=\"font-family: 宋体;\">綜合擴音機、後級擴大機及喇叭。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;</span></p>\r\n<p><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c874bb3d01.jpg\" alt=\"\" width=\"421\" height=\"280\" /></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;雖然兩套不同系統的要求有所不同，因為空間有限而需要把喇叭合併也未嘗不可，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">但要記住的一套能聽好音樂的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">喇叭也可以合適看電影，更可以打造出猶如劇院般的效果，但一套合適看電影的喇叭，卻未必合適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">聽音樂</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;單看價錢便知道，一套簡單的家庭影院系統可能千多</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">元也</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">有，但一套入門</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">級</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的純音樂兩聲道系統可能</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">已</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要數千元，喇叭還比家庭影院系統的少，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">憑這些</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">便知道兩者之間</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">喇叭</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">水準一定有別</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"height: 409px; width: 334px; border-collapse: collapse; float: right;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 423px;\">\r\n<td style=\"width: 326px; height: 339px;\">\r\n<table style=\"width: 360px; border-collapse: collapse; float: right; height: 343px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 419px;\">\r\n<td style=\"width: 334px; height: 351px;\"><img style=\"font-family: 宋体; font-size: 16px; margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874b81a58.jpg\" width=\"155\" height=\"233\" /><img style=\"font-family: 宋体; font-size: 16px; margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874bd31b3.jpg\" width=\"175\" height=\"233\" /><img style=\"margin-right: 0px; margin-left: 0px;\" src=\"/mas_studio/storage/image/20180103/5a4c874b9a3a7.jpg\" width=\"329\" height=\"160\" /><br /><br /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;香港地方有限，並不是每個家庭也可以擁有獨立的私人影院，只能把客廳與私人影院合二為一，雖然因為空間問題有所限制而不可打造出一個完美</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">獨立的私人影院，但要造出一個優質的視聽客廳也需要注意些事項，首先在設計前要先考慮好器材、線的接駁及材料、器材擺放的角度及位置、牆身的物料及吸音問題等，我們逐點說解一下:</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">裝修前要選定好器材，你需要的是一個家庭影院還是只聽純音樂的兩聲道系統，大家要明白兩者之間的系統是有所不同的，家庭影院的系統就是一套「迷你電影院」，於座位的四周圍設置多支喇叭、再利用環繞音效處理讓聲響從不同位置的喇叭以不同的音量發出，就能讓觀賞者感受如身歷其境的效果。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;簡單一點就是平常說的5.1、<span style=\"font-family: Calibri;\">7.1</span>，而當中的<span style=\"font-family: Calibri;\">5</span>及<span style=\"font-family: Calibri;\">7</span>是代表著喇叭的數量，點後的<span style=\"font-family: Calibri;\">1</span>字是代表著重低音喇叭<span style=\"font-family: Calibri;\">(</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;subwoofer)</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的數量。當中包括:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;中置&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;Center</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">為人聲、主要音樂及中間方向音效的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">發聲位置</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，所有主要的聲音都由這裡發出。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">主喇叭&nbsp;/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">前置&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;L</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、R)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">來自前左及前右的聲音，營造出整個音場的氣勢、音樂及音效。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;重低音&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">subwoofer) &ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">發出極低頻的聲響，在觀看電影、音樂會時更震撼，若果空間很大，而一支重低音喇叭不足夠提供低音的震撼感，便需要兩支或以上的重低音。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;環繞喇叭&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;SL</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、SR)&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">來自左右環繞的音效，令音場環繞及空間感更完整。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;後置喇叭&nbsp;(</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">SBL、<span style=\"font-family: Calibri;\">SBR)</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;&ndash;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;是7.1聲道增加的喇叭，來自後左及後右的聲音，當然越多喇叭也就能營造的聲音效果包圍感就越好。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">而且</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">家庭影院系統還要配上藍光播放機、AV擴音機&nbsp;<span style=\"font-family: Calibri;\">/</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">環繞擴音機&nbsp;(Amplifier)&nbsp;、電視、投影機、銀幕等。而純音樂的兩聲道系統配上的器材是<span style=\"font-family: Calibri;\">player (CD</span>機<span style=\"font-family: Calibri;\">/</span>黑膠唱片、或是存放&nbsp;<span style=\"font-family: Calibri;\">MP3&nbsp;</span>等數位音樂檔案的電腦等<span style=\"font-family: Calibri;\">)&nbsp;</span>、前級擴音機</span><span style=\"font-family: Calibri;\">/&nbsp;</span><span style=\"font-family: 宋体;\">綜合擴音機、後級擴大機及喇叭。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;</span></p>\r\n<p><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c874bb3d01.jpg\" alt=\"\" width=\"421\" height=\"280\" /></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;雖然兩套不同系統的要求有所不同，因為空間有限而需要把喇叭合併也未嘗不可，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">但要記住的一套能聽好音樂的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">喇叭也可以合適看電影，更可以打造出猶如劇院般的效果，但一套合適看電影的喇叭，卻未必合適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">聽音樂</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;單看價錢便知道，一套簡單的家庭影院系統可能千多</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">元也</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">有，但一套入門</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">級</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的純音樂兩聲道系統可能</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">已</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要數千元，喇叭還比家庭影院系統的少，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">憑這些</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">便知道兩者之間</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">喇叭</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">水準一定有別</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n</body>\r\n</html>', '[\"802\"]', '13', '1');
INSERT INTO `mg_z_column` VALUES ('16', '客廳·影音視聽空間 (二)', '客廳·影音視聽空間 (二)', '617期', '617期', '807', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img src=\"/mas_studio/storage/image/20180103/5a4c89716d130.jpg\" alt=\"\" width=\"407\" height=\"268\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c8971289cb.jpg\" alt=\"\" width=\"401\" height=\"269\" /></span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;做事要變通，在香港生活空間更要靈活多變，才可以做到麻雀雖小又五臟俱全，要在家中打造一個優質的視聽客廳不是困難，但當中也有不少事是需要注意的，上期我們討論過家庭影院系統與只聽純音樂的兩聲道系統的分別，雖然是兩套不同的系統，但空間有限是否可以把兩套系統合併</span>?</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">這便牽涉到我們第二個話題</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">預算：</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">在裝修前需要決定好將來會選用的視</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">聽器材</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，如</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">之前提</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">到想要兩聲道系統同時又</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">想有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">家庭影院系統，兩者之間是可以合併，但要記住的是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">能聽好音樂的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">喇叭絕對合適看電影，但只合適看電影的喇叭卻未必合適</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">聽音樂</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。如果預算許可的情況下絕對可以把家庭劇院系統及按著純音樂兩聲道系統的標準來造，出來的效果必定超越不少戲院，當然價格也是不菲，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不是每人也能負擔到。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;另一個方法是直接把純音樂的兩聲道系統融入家庭影院中作為主喇叭，只要額外配置中置喇叭、環繞喇叭、重低音喇叭等等的設備便可以把兩套系統合併。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不過要提一提，中置喇叭在家庭影院中也擔任一個重要的角色，不論是電影</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">演唱會或是歌星唱歌也好，百分之九十以上的人聲也是靠中置喇叭發出，所以如果你選擇等級較高的主聲道喇叭時建議也選用同一級別的中置喇叭，要不</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">然</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">當觀看電影時主角說話比背景音樂音效差很遠時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">一定會影響你觀看電影的氣氛。但如果預算不足又或者對影音要求不高的，建議購買市面上一套過的</span>5.1</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">7.1</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">閒時來觀</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">賞</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">一下電影</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">已</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">足夠。</span></span></p>\r\n<p class=\"MsoNormal\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp;</span><br /><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">選擇器材：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">對初入門者來說，選擇器材時一定要多做功課，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">除</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">了透過朋友、展</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">覽、雜誌、網路之外也要多去音響店逛逛，總要試聽一下累積實戰經驗培養對聲音的敏銳度與相關的專業知識。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">同時了解自己</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的需求: 如藍光播放機、環繞擴音機 <span style=\"font-family: Calibri;\">(Amplifier) </span>、電視、投影機、銀幕、線</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">材、音樂<span style=\"font-family: Calibri;\">player</span>、前級擴音機 <span style=\"font-family: Calibri;\">/ </span>綜合擴音機及各喇叭。再鎖定<span style=\"font-family: Calibri;\">2-3</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">個品牌作對比，另外選擇較有信譽的品牌，而且在購買前可聘請專業視聽p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">lanner </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">或者多聽音響店內的專家建議，</span></p>\r\n<p class=\"MsoNormal\"><img style=\"text-indent: -24px; font-family: 宋体; font-size: 16px; float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c89711b08d.jpg\" width=\"263\" height=\"175\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">亦</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">準備</span><img style=\"font-family: 宋体; font-size: 16px; float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8970ed161.jpg\" alt=\"\" width=\"341\" height=\"227\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一些資料如客廳的尺寸大小等，因為不同形狀、距離的空間對選擇器材也有影響，最簡單的是大的空間有更多的空氣需要被振動，需要提供額外音量及較大輸出功率的喇叭，相對較小空間的客廳便可使用較小的喇叭。當然你可要求視聽p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">lanner</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">先到你的家中進行量度及測試給你一個規劃便最好。</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><img src=\"/mas_studio/storage/image/20180103/5a4c89716d130.jpg\" alt=\"\" width=\"407\" height=\"268\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c8971289cb.jpg\" alt=\"\" width=\"401\" height=\"269\" /></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;做事要變通，在香港生活空間更要靈活多變，才可以做到麻雀雖小又五臟俱全，要在家中打造一個優質的視聽客廳不是困難，但當中也有不少事是需要注意的，上期我們討論過家庭影院系統與只聽純音樂的兩聲道系統的分別，雖然是兩套不同的系統，但空間有限是否可以把兩套系統合併?</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">這便牽涉到我們第二個話題:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">預算：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">在裝修前需要決定好將來會選用的視</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">聽器材</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，如</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">之前提</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">到想要兩聲道系統同時又</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">想有</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">家庭影院系統，兩者之間是可以合併，但要記住的是</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">能聽好音樂的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">喇叭絕對合適看電影，但只合適看電影的喇叭卻未必合適</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">聽音樂</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。如果預算許可的情況下絕對可以把家庭劇院系統及按著純音樂兩聲道系統的標準來造，出來的效果必定超越不少戲院，當然價格也是不菲，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">亦</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">不是每人也能負擔到。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;另一個方法是直接把純音樂的兩聲道系統融入家庭影院中作為主喇叭，只要額外配置中置喇叭、環繞喇叭、重低音喇叭等等的設備便可以把兩套系統合併。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">不過要提一提，中置喇叭在家庭影院中也擔任一個重要的角色，不論是電影</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">演唱會或是歌星唱歌也好，百分之九十以上的人聲也是靠中置喇叭發出，所以如果你選擇等級較高的主聲道喇叭時建議也選用同一級別的中置喇叭，要不</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">然</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">當觀看電影時主角說話比背景音樂音效差很遠時</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一定會影響你觀看電影的氣氛。但如果預算不足又或者對影音要求不高的，建議購買市面上一套過的5.1</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">7.1</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">閒時來觀</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">賞</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一下電影</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">已</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">足夠。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp;</span><br /><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">選擇器材：</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">對初入門者來說，選擇器材時一定要多做功課，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">除</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">了透過朋友、展</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">覽、雜誌、網路之外也要多去音響店逛逛，總要試聽一下累積實戰經驗培養對聲音的敏銳度與相關的專業知識。</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">同時了解自己</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的需求: 如藍光播放機、環繞擴音機&nbsp;<span style=\"font-family: Calibri;\">(Amplifier)&nbsp;</span>、電視、投影機、銀幕、線</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">材、音樂<span style=\"font-family: Calibri;\">player</span>、前級擴音機&nbsp;<span style=\"font-family: Calibri;\">/&nbsp;</span>綜合擴音機及各喇叭。再鎖定<span style=\"font-family: Calibri;\">2-3</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">個品牌作對比，另外選擇較有信譽的品牌，而且在購買前可聘請專業視聽p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">lanner&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">或者多聽音響店內的專家建議，</span></p>\r\n<p class=\"MsoNormal\"><img style=\"text-indent: -24px; font-family: 宋体; font-size: 16px; float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c89711b08d.jpg\" width=\"263\" height=\"175\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">亦</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">準備</span><img style=\"font-family: 宋体; font-size: 16px; float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8970ed161.jpg\" alt=\"\" width=\"341\" height=\"227\" /><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">一些資料如客廳的尺寸大小等，因為不同形狀、距離的空間對選擇器材也有影響，最簡單的是大的空間有更多的空氣需要被振動，需要提供額外音量及較大輸出功率的喇叭，相對較小空間的客廳便可使用較小的喇叭。當然你可要求視聽p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">lanner</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">先到你的家中進行量度及測試給你一個規劃便最好。</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p>\r\n</body>\r\n</html>', '[\"807\"]', '14', '1');
INSERT INTO `mg_z_column` VALUES ('17', '客廳·影音視聽空間 (三)', '客廳·影音視聽空間 (三)', '618期', '618期', '812', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span>&nbsp;&nbsp;</span></span></p>\r\n<table style=\"width: 232px; border-collapse: collapse; float: right; height: 379px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 383px;\">\r\n<td style=\"width: 216px; height: 383px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c8a66ede28.jpg\" alt=\"\" width=\"196\" height=\"130\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8a6713526.jpg\" alt=\"\" width=\"198\" height=\"117\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8a672ff47.jpg\" alt=\"\" width=\"201\" height=\"121\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span>&nbsp; &nbsp;想擁有一個私人影院但屋</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>企空間有限</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>，把客廳與私人影院合二為一，要打造一個優質的視聽客廳絕對不難，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>但也有不少事項要注意</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>。上兩期我們討論過</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>家庭影院系統與純音樂兩聲道系統的分別、預算、選擇器材。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span>一般的喇叭擺放位置也是人與喇叭的搭配最好能呈現正三角形的方式，以人的位置作基準頂點，以倒正三角形向二側延伸，這就是聆聽的最好角度。但每間屋的客廳、尺寸、設計及裝飾也有不同，所以在裝修設計及選擇器材之前還是最好找來專業視聽</span>p</span><span style=\"font-family: Calibri; font-size: 12pt;\">lanner&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>或者多聽音響店內的專家到現場來做完整的測試和音場調整並聽取他們的建議，要打造一個好的視聽空間不單關係到美感、舒適、方便等的問題，也不是只購買貴價的器材便可，要規劃出最優質的空間來將影音品質發揮到極致才能享受最完美的視聽娛樂空間。而當中要考慮到聲學的特性，器材擺放的位置、吸音的設計等，如有不足便會產生中高音導向混亂、吸音過度或者不足等的有害聲音污染因素，到時便得不償失了。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span>&nbsp; &nbsp;有關喇叭、大小、距離、位置等，每個空間各有不同所以也不</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>便</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>在此說太多，但相對視頻設備便簡單</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>得</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>多，主要是銀幕，要考慮牆身的寬度和高度以及長度尺寸，大部分採用</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">16:9</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>和</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">2.35:1</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>兩種格式。另外便是</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">4K</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>高清投影機，在選擇時也要考慮投影機的成像類型、光源類型及亮度等因素。另外在室內設計選用的牆身飾面方面要考慮銀幕的周圍盡量</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>不要選用</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span>太淡或者光滑反光的物料，這些雜亂光源會影響觀眾的視覺效果。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span>&nbsp;</span></span><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8a66d6d4a.jpg\" alt=\"\" width=\"315\" height=\"282\" /><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;&nbsp;在選擇器材的時候也可以和室內設計師討論一下怎樣才可配合整個設計，當然主要的器材/喇叭是不可避免，但線</span><span style=\"font-family: 宋体; font-size: 12pt;\">位</span><span style=\"font-family: 宋体; font-size: 12pt;\">的接駁、如何隱藏/收納也是十分重要，還有影視器材的藍光播放機、環繞擴音機、音樂<span style=\"font-family: Calibri;\">player</span>、綜合擴音機等等，最好造一個木的櫃子把它們儲放好，但要緊記櫃子後方做好散熱及預留管線的位置、最好放在喇叭後一點，才不會影響喇叭的聲波震動，避免反射的情形。 若有櫃的設計，門要採用玻璃門，</span><span style=\"font-family: 宋体; font-size: 12pt;\">否則</span><span style=\"font-family: 宋体; font-size: 12pt;\">遙控器接觸不</span><span style=\"font-family: 宋体; font-size: 12pt;\">良</span><span style=\"font-family: 宋体; font-size: 12pt;\">便要每次把門打開也太不放便了，最後也要預留多餘的空間待日後器材升級時用。另外可利用電動升降的架子把投影機藏在假天花，相對直接把投影機吊在天花令整個空間更簡潔，需要時再按遙控器將其放下即可。若空間或者真的在意沙發後方有兩支喇叭懸掛在天花的話</span><span style=\"font-family: 宋体; font-size: 12pt;\">亦</span><span style=\"font-family: 宋体; font-size: 12pt;\">可選用嵌入式的喇叭也是個不錯的選擇。</span></p>\r\n<p><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;</span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp;&nbsp;</span></span></p>\r\n<table style=\"width: 232px; border-collapse: collapse; float: right; height: 379px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 383px;\">\r\n<td style=\"width: 216px; height: 383px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c8a66ede28.jpg\" alt=\"\" width=\"196\" height=\"130\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8a6713526.jpg\" alt=\"\" width=\"198\" height=\"117\" /><img src=\"/mas_studio/storage/image/20180103/5a4c8a672ff47.jpg\" alt=\"\" width=\"201\" height=\"121\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;想擁有一個私人影院但屋</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">企空間有限</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，把客廳與私人影院合二為一，要打造一個優質的視聽客廳絕對不難，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">但也有不少事項要注意</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">。上兩期我們討論過</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">家庭影院系統與純音樂兩聲道系統的分別、預算、選擇器材。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">一般的喇叭擺放位置也是人與喇叭的搭配最好能呈現正三角形的方式，以人的位置作基準頂點，以倒正三角形向二側延伸，這就是聆聽的最好角度。但每間屋的客廳、尺寸、設計及裝飾也有不同，所以在裝修設計及選擇器材之前還是最好找來專業視聽</span>p</span><span style=\"font-family: Calibri; font-size: 12pt;\">lanner&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">或者多聽音響店內的專家到現場來做完整的測試和音場調整並聽取他們的建議，要打造一個好的視聽空間不單關係到美感、舒適、方便等的問題，也不是只購買貴價的器材便可，要規劃出最優質的空間來將影音品質發揮到極致才能享受最完美的視聽娛樂空間。而當中要考慮到聲學的特性，器材擺放的位置、吸音的設計等，如有不足便會產生中高音導向混亂、吸音過度或者不足等的有害聲音污染因素，到時便得不償失了。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;有關喇叭、大小、距離、位置等，每個空間各有不同所以也不</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">便</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">在此說太多，但相對視頻設備便簡單</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">得</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">多，主要是銀幕，要考慮牆身的寬度和高度以及長度尺寸，大部分採用</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">16:9</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">和</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">2.35:1</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">兩種格式。另外便是</span></span><span style=\"font-family: Calibri; font-size: 12pt;\">4K</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">高清投影機，在選擇時也要考慮投影機的成像類型、光源類型及亮度等因素。另外在室內設計選用的牆身飾面方面要考慮銀幕的周圍盡量</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">不要選用</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">太淡或者光滑反光的物料，這些雜亂光源會影響觀眾的視覺效果。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8a66d6d4a.jpg\" alt=\"\" width=\"315\" height=\"282\" /><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;&nbsp;在選擇器材的時候也可以和室內設計師討論一下怎樣才可配合整個設計，當然主要的器材/喇叭是不可避免，但線</span><span style=\"font-family: 宋体; font-size: 12pt;\">位</span><span style=\"font-family: 宋体; font-size: 12pt;\">的接駁、如何隱藏/收納也是十分重要，還有影視器材的藍光播放機、環繞擴音機、音樂<span style=\"font-family: Calibri;\">player</span>、綜合擴音機等等，最好造一個木的櫃子把它們儲放好，但要緊記櫃子後方做好散熱及預留管線的位置、最好放在喇叭後一點，才不會影響喇叭的聲波震動，避免反射的情形。 若有櫃的設計，門要採用玻璃門，</span><span style=\"font-family: 宋体; font-size: 12pt;\">否則</span><span style=\"font-family: 宋体; font-size: 12pt;\">遙控器接觸不</span><span style=\"font-family: 宋体; font-size: 12pt;\">良</span><span style=\"font-family: 宋体; font-size: 12pt;\">便要每次把門打開也太不放便了，最後也要預留多餘的空間待日後器材升級時用。另外可利用電動升降的架子把投影機藏在假天花，相對直接把投影機吊在天花令整個空間更簡潔，需要時再按遙控器將其放下即可。若空間或者真的在意沙發後方有兩支喇叭懸掛在天花的話</span><span style=\"font-family: 宋体; font-size: 12pt;\">亦</span><span style=\"font-family: 宋体; font-size: 12pt;\">可選用嵌入式的喇叭也是個不錯的選擇。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n</body>\r\n</html>', '[\"812\"]', '15', '1');
INSERT INTO `mg_z_column` VALUES ('18', '客廳·影音視聽空間 (四)', '客廳·影音視聽空間 (四)', '619期', '619期', '816', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 346px; border-collapse: collapse; float: right; height: 306px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 326px;\">\r\n<td style=\"width: 342px; height: 341px; text-align: center;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c8b9ae8210.jpg\" alt=\"\" width=\"155\" height=\"233\" />&nbsp;<img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8b9b0e0b5.jpg\" width=\"156\" height=\"234\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;要在有限的空間打造出一個影音視聽空間也絕不可馬虎，當中有不少的事項需要注意，如我們早幾期已講解過的在裝修</span><span style=\"font-family: 宋体; font-size: 12pt;\">前</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">便</span><span style=\"font-family: 宋体; font-size: 12pt;\">要先決定好只要家庭影院系統或是純音樂兩聲道系統，兩者當中的分別又是怎樣?</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">若把兩套系統合併又如果呢?同時要大致</span><span style=\"font-family: 宋体; font-size: 12pt;\">了</span><span style=\"font-family: 宋体; font-size: 12pt;\">解器材的品牌及價格準備預算，另外在購買器材前最好聘請專業的視聽設計師或者諮詢音響店內的專家，到家中先視察環境了解面積大小及器材的擺放位置等。當然小不了與室內設計師一同商討設計風格、物料及隔音/吸音等問題，而這個也就是我們這期討論的項目<span style=\"font-family: Calibri;\">:</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;一個視聽空間一定需要隔音，隔音不單止</span><span style=\"font-family: 宋体; font-size: 12pt;\">防止</span><span style=\"font-family: 宋体; font-size: 12pt;\">視聽室內的聲音傳到外面影響別人</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">同時也不讓外面的聲音傳入視聽室內影響內部效果。首先是牆結構的處理，在結構牆表面多加一層木榔，在內塞滿隔音棉及封上多層石膏板，同時也可在石膏板中間可考慮夾上隔音膠便可做到更好的隔音效果。也要留意天花板的處理，天花板是視聽室裝修隔音中容易被忽略的地方，處理方法也十分簡單和牆身大致相同也是用上木榔再加上吸音棉並封上石膏板。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\">再者便要解決門的問題，這個有點複雜也</span><span style=\"font-family: 宋体; font-size: 12pt;\">不可以</span><span style=\"font-family: 宋体; font-size: 12pt;\">買普通的門及門框，可以用上中空木門把吸音棉塞滿內部，門背需要貼上隔音氈及隔音棉並作外層包裹，而門框同樣的要做密封處理，門與門框之間也要用上橡膠條保證緊密連接以做到隔音的效果。另外還有玻璃窗，一個真正獨立的私人影院是不會有窗的</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">但多數的客廳也必有玻璃窗，所以也要換上雙層的隔音玻璃窗。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; 除了牆身、門及窗之外選用的物料也十分重要，如果選錯了物料會影響吸音比率的控制，一般來說地台飾面</span><span style=\"font-family: 宋体; font-size: 12pt;\">用</span><span style=\"font-family: 宋体; font-size: 12pt;\">上木地板</span><span style=\"font-family: 宋体; font-size: 12pt;\">或地</span><span style=\"font-family: 宋体; font-size: 12pt;\">毯可輔助吸音，</span><span style=\"font-family: 宋体; font-size: 12pt;\">而</span><span style=\"font-family: 宋体; font-size: 12pt;\">地台及牆身也要避免</span><span style=\"font-family: 宋体; font-size: 12pt;\">用</span><span style=\"font-family: 宋体; font-size: 12pt;\">瓷磚、雲石、玻璃及鏡子等，因為這些物料容易產生共振，而且吸音效果差。可選用多一些軟性材質、如木材、厚布料、窗簾、地毯、牆布、牆身毯等吸</span><span style=\"font-family: 宋体; font-size: 12pt;\">納</span><span style=\"font-family: 宋体; font-size: 12pt;\">噪音。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8b9acd3fd.jpg\" alt=\"\" width=\"470\" height=\"312\" />&nbsp; &nbsp;除了隔音/吸音的問題之外，還要考慮到聲波的擴散作用，才能讓環繞產生絕佳的效果，在客廳可利用電視主牆，用造型版做出弧面或是椎面壁牆來幫助聲波擴展，或利用造型吸音棉及軟木來讓聲音擴散，提升環繞音質。這些資料最好先與設計師研究及商討再合併整個房子的設計風格，便可以打造出一個又實用又美觀的客廳。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;當完成及安裝</span><span style=\"font-family: 宋体; font-size: 12pt;\">所有器材</span><span style=\"font-family: 宋体; font-size: 12pt;\">，便到最後由專家來調校及設定喇叭，先座在皇帝位，用上測距儀再把數據輸入計算出適當的延遲時間，讓所有喇叭傳送的聲音可同時到達聽者的位置，最後也就是調整一下音壓讓聲音更立體便完成。</span></p>\r\n<p><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp;</span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 346px; border-collapse: collapse; float: right; height: 306px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 326px;\">\r\n<td style=\"width: 342px; height: 341px; text-align: center;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c8b9ae8210.jpg\" alt=\"\" width=\"155\" height=\"233\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c8b9b0e0b5.jpg\" alt=\"\" width=\"156\" height=\"234\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;要在有限的空間打造出一個影音視聽空間也絕不可馬虎，當中有不少的事項需要注意，如我們早幾期已講解過的在裝修</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">前</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">便</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">要先決定好只要家庭影院系統或是純音樂兩聲道系統，兩者當中的分別又是怎樣</span>?</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">若把兩套系統合併又如果呢</span>?<span style=\"font-family: 宋体;\">同時要大致</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">了</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">解器材的品牌及價格準備預算，另外在購買器材前最好聘請專業的視聽設計師或者諮詢音響店內的專家，到家中先視察環境了解面積大小及器材的擺放位置等。當然小不了與室內設計師一同商討設計風格、物料及隔音</span>/<span style=\"font-family: 宋体;\">吸音等問題，而這個也就是我們這期討論的項目</span><span style=\"font-family: Calibri;\">:</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;一個視聽空間一定需要隔音，隔音不單止</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">防止</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">視聽室內的聲音傳到外面影響別人</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">同時也不讓外面的聲音傳入視聽室內影響內部效果。首先是牆結構的處理，在結構牆表面多加一層木榔，在內塞滿隔音棉及封上多層石膏板，同時也可在石膏板中間可考慮夾上隔音膠便可做到更好的隔音效果。也要留意天花板的處理，天花板是視聽室裝修隔音中容易被忽略的地方，處理方法也十分簡單和牆身大致相同也是用上木榔再加上吸音棉並封上石膏板。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24pt;\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">再者便要解決門的問題，這個有點複雜也</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">不可以</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">買普通的門及門框，可以用上中空木門把吸音棉塞滿內部，門背需要貼上隔音氈及隔音棉並作外層包裹，而門框同樣的要做密封處理，門與門框之間也要用上橡膠條保證緊密連接以做到隔音的效果。另外還有玻璃窗，一個真正獨立的私人影院是不會有窗的</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">但多數的客廳也必有玻璃窗，所以也要換上雙層的隔音玻璃窗。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; 除了牆身、門及窗之外選用的物料也十分重要，如果選錯了物料會影響吸音比率的控制，一般來說地台飾面</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">用</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">上木地板</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">或地</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">毯可輔助吸音，</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">而</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">地台及牆身也要避免</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">用</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">瓷磚、雲石、玻璃及鏡子等，因為這些物料容易產生共振，而且吸音效果差。可選用多一些軟性材質、如木材、厚布料、窗簾、地毯、牆布、牆身毯等吸</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">納</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">噪音。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\"><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8b9acd3fd.jpg\" alt=\"\" width=\"470\" height=\"312\" />&nbsp; &nbsp;除了隔音</span>/<span style=\"font-family: 宋体;\">吸音的問題之外，還要考慮到聲波的擴散作用，才能讓環繞產生絕佳的效果，在客廳可利用電視主牆，用造型版做出弧面或是椎面壁牆來幫助聲波擴展，或利用造型吸音棉及軟木來讓聲音擴散，提升環繞音質。這些資料最好先與設計師研究及商討再合併整個房子的設計風格，便可以打造出一個又實用又美觀的客廳。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;當完成及安裝</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">所有器材</span></span><span style=\"font-family: 宋体; font-size: 12pt;\"><span style=\"font-family: 宋体;\">，便到最後由專家來調校及設定喇叭，先座在皇帝位，用上測距儀再把數據輸入計算出適當的延遲時間，讓所有喇叭傳送的聲音可同時到達聽者的位置，最後也就是調整一下音壓讓聲音更立體便完成。</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n</body>\r\n</html>', '[\"816\"]', '16', '1');
INSERT INTO `mg_z_column` VALUES ('19', '「林」の和室', '「林」の和室', '620期', '620期', '822', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;&nbsp;&nbsp;</span></span></p>\r\n<table style=\"width: 214px; border-collapse: collapse; float: right; height: 573px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 210px;\">\r\n<p style=\"text-align: right;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cd5e7a17.jpg\" alt=\"\" width=\"202\" height=\"134\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c8cd99c3ec.jpg\" alt=\"\" width=\"201\" height=\"134\" /></p>\r\n<p><img style=\"text-indent: 32px; float: right; margin-bottom: 12px; margin-top: 12px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdc7cca1.jpg\" width=\"201\" height=\"135\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdbe5f61.jpg\" alt=\"\" width=\"201\" height=\"135\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">「林」の</span> <span style=\"font-family: 宋体;\">和室</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;｢侘寂（</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Wabi-sabi</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">）｣，日本傳統美學中最顯著的特點，包括不對稱，粗糙或不規則，簡單，經濟，低調，親密和展現自然的完整性。當中總是被那看似平淡、簡樸，實則處處牽動著人們內心情緒的「氛圍」所吸引著，那是一種難以言喻的「感覺」，一種沁到心靈深處的韻味</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;位於灣仔活道</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">香港首家日本餐廳獲得米芝蓮一星榮譽</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">的著名懷石料理食府</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Kaiseki Den by Saotome</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。日式的設計元素</span>, <span style=\"font-family: 宋体;\">簡樸高雅 </span><span style=\"font-family: Calibri;\">- </span><span style=\"font-family: 宋体;\">摒棄繁瑣複雜的線，採用清晰的裝飾線條，給人以寬敞明亮的感覺。採用天然裝修樸實的材料 </span><span style=\"font-family: Calibri;\">- </span><span style=\"font-family: 宋体;\">展示出一種祥和與寧靜的意境及心態。讓室內仿如置身世外桃源，遠離城市喧囂。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">店面以環保戶外木造出凹凸簡潔線條配柔和燈光</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">營造出強調的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">幾何立體感</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，設計雖簡潔卻在總多店中突顯出她的與別不同</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">條子設計的大門配合上和紙的夾層玻璃</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">與傳統日式障子設計造出透光的效果美觀之餘又注重防水的實用。入內便是由日式園景設計概念以竹林、石春、大石、石水盆及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">石</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">燈籠組合而成的走廊，經過此走廊仿佛是身在世外桃源如洗滌煩憂的心靈</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">摒棄繁瑣的事情進入舒適又平靜的主餐室。</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">主餐區主要分為開放式廚房的吧台及兩個貴賓室，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">地台的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">飾面選用酸蝕面的大理石地台、以竹皮及牆紙造成的牆身飾面及木紋面的鋁質條子半開放式天花，全都採用天然樸實的材料，同時儘量保持原色不加修飾，這種親近自然的裝修展示出一種祥和的生活意境與寧靜致遠的生活</span></span><span style=\"font-family: 宋体; font-size: 12pt; text-indent: 24pt;\">心態。在開放式廚房的吧台上用貼有和紙的燈箱，柔和簡潔透光的燈箱設計增加寬敞明亮的感覺，以擴大整個空間視野範圍，也充分體現出日式風格的沉靜簡潔。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img style=\"float: left; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdcb4f99.jpg\" width=\"467\" height=\"312\" />貴賓室的設計與傳統和室設計相同，由障子作為分隔，拉上障子便成了獨立空間，全開時便擁有開闊場域的空間，而障子設計與大門相近由和紙造成透光度高，加上木格子以間距密集的長方條組成，增加遮蔽性，更增加整體的日式風格。另一面便是擁有</span>5<span style=\"font-family: 宋体;\">米高的貴賓室，整個房間高位造了與主餐室相同柔和簡潔的透光燈箱，令整體空間的燈光更柔和及舒適，效果牆設計概念來自日本特有的庭園景觀之「枯山水」具深遠禪意的侘寂之美，枯山水顧名思義就是乾枯山水，以波浪紋表達「水」的流動，同時利用圓形設計來代表園景中的石即「山」，整面牆身用上綠色的牆紙營造出寧靜的氛圍。也配搭上簡單的綠色植物、茶具等的裝飾為整體設計更 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;充分體現出日式風格的沉靜簡潔。</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\">&nbsp;</p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<table style=\"width: 214px; border-collapse: collapse; float: right; height: 573px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 210px;\">\r\n<p style=\"text-align: right;\"><img style=\"font-family: 宋体; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cd5e7a17.jpg\" alt=\"\" width=\"202\" height=\"134\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c8cd99c3ec.jpg\" alt=\"\" width=\"201\" height=\"134\" /></p>\r\n<p><img style=\"text-indent: 32px; float: right; margin-bottom: 12px; margin-top: 12px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdc7cca1.jpg\" width=\"201\" height=\"135\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdbe5f61.jpg\" alt=\"\" width=\"201\" height=\"135\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">「林」の&nbsp;和室</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp; &nbsp;｢侘寂（</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Wabi-sabi</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">）｣，日本傳統美學中最顯著的特點，包括不對稱，粗糙或不規則，簡單，經濟，低調，親密和展現自然的完整性。當中總是被那看似平淡、簡樸，實則處處牽動著人們內心情緒的「氛圍」所吸引著，那是一種難以言喻的「感覺」，一種沁到心靈深處的韻味</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">&nbsp; &nbsp;位於灣仔活道</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">香港首家日本餐廳獲得米芝蓮一星榮譽</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">的著名懷石料理食府</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">Kaiseki Den by Saotome</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。日式的設計元素,&nbsp;簡樸高雅&nbsp;<span style=\"font-family: Calibri;\">-&nbsp;</span>摒棄繁瑣複雜的線，採用清晰的裝飾線條，給人以寬敞明亮的感覺。採用天然裝修樸實的材料&nbsp;<span style=\"font-family: Calibri;\">-&nbsp;</span>展示出一種祥和與寧靜的意境及心態。讓室內仿如置身世外桃源，遠離城市喧囂。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">店面以環保戶外木造出凹凸簡潔線條配柔和燈光</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">營造出強調的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">幾何立體感</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，設計雖簡潔卻在總多店中突顯出她的與別不同</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">條子設計的大門配合上和紙的夾層玻璃</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: Arial; font-size: 12.0000pt; mso-font-kerning: 0.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">與傳統日式障子設計造出透光的效果美觀之餘又注重防水的實用。入內便是由日式園景設計概念以竹林、石春、大石、石水盆及</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">石</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">燈籠組合而成的走廊，經過此走廊仿佛是身在世外桃源如洗滌煩憂的心靈</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">摒棄繁瑣的事情進入舒適又平靜的主餐室。</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">主餐區主要分為開放式廚房的吧台及兩個貴賓室，</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">地台的</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">飾面選用酸蝕面的大理石地台、以竹皮及牆紙造成的牆身飾面及木紋面的鋁質條子半開放式天花，全都採用天然樸實的材料，同時儘量保持原色不加修飾，這種親近自然的裝修展示出一種祥和的生活意境與寧靜致遠的生活</span><span style=\"font-family: 宋体; font-size: 12pt; text-indent: 24pt;\">心態。在開放式廚房的吧台上用貼有和紙的燈箱，柔和簡潔透光的燈箱設計增加寬敞明亮的感覺，以擴大整個空間視野範圍，也充分體現出日式風格的沉靜簡潔。</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: 24.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><img style=\"float: left; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c8cdcb4f99.jpg\" width=\"467\" height=\"312\" />貴賓室的設計與傳統和室設計相同，由障子作為分隔，拉上障子便成了獨立空間，全開時便擁有開闊場域的空間，而障子設計與大門相近由和紙造成透光度高，加上木格子以間距密集的長方條組成，增加遮蔽性，更增加整體的日式風格。另一面便是擁有5米高的貴賓室，整個房間高位造了與主餐室相同柔和簡潔的透光燈箱，令整體空間的燈光更柔和及舒適，效果牆設計概念來自日本特有的庭園景觀之「枯山水」具深遠禪意的侘寂之美，枯山水顧名思義就是乾枯山水，以波浪紋表達「水」的流動，同時利用圓形設計來代表園景中的石即「山」，整面牆身用上綠色的牆紙營造出寧靜的氛圍。也配搭上簡單的綠色植物、茶具等的裝飾為整體設計更充分體現出日式風格的沉靜簡潔。</span></p>\r\n</body>\r\n</html>', '[\"822\"]', '17', '1');
INSERT INTO `mg_z_column` VALUES ('20', '我與毛孩的生活(上)', '我與毛孩的生活(上)', '621期', '621期', '827', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<table style=\"height: 168px; width: 195px; border-collapse: collapse; float: right;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 291px;\">\r\n<td style=\"width: 203px; height: 459px; border-style: none;\">\r\n<p><img style=\"font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba468dc.jpg\" width=\"193\" height=\"193\" /><img style=\"font-family: 宋体; font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba04781.jpg\" width=\"193\" height=\"291\" /></p>\r\n<p><img style=\"font-family: 宋体; font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba500a3.jpg\" width=\"194\" height=\"129\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;毛孩已不</span><span style=\"font-family: 宋体; font-size: 12pt;\">只</span><span style=\"font-family: 宋体; font-size: 12pt;\">是寵物，</span><span style=\"font-family: 宋体; font-size: 12pt;\">而是我們生活</span><span style=\"font-family: 宋体; font-size: 12pt;\">或</span><span style=\"font-family: 宋体; font-size: 12pt;\">家中</span><span style=\"font-family: 宋体; font-size: 12pt;\">的一份子</span><span style=\"font-family: 宋体; font-size: 12pt;\">，猶如親生孩子一樣</span><span style=\"font-family: 宋体; font-size: 12pt;\">，對於牠們的生活所需、健康等問題也需要細心照料，</span><span style=\"font-family: 宋体; font-size: 12pt;\">除基本飲食外</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">生活環境更為重要，所以在設計規劃時也要考慮到牠們所需。我們可先</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">說一下牠們</span><span style=\"font-family: 宋体; font-size: 12pt;\">共</span><span style=\"font-family: 宋体; font-size: 12pt;\">通的特色</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">好讓大家在設計時</span><span style=\"font-family: 宋体; font-size: 12pt;\">有所</span><span style=\"font-family: 宋体; font-size: 12pt;\">考慮</span><span style=\"font-family: Calibri; font-size: 12pt;\">;</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">但要打造出</span><span style=\"font-family: 宋体; font-size: 12pt;\">既</span><span style=\"font-family: 宋体; font-size: 12pt;\">適</span><span style=\"font-family: 宋体; font-size: 12pt;\">合</span><span style=\"font-family: 宋体; font-size: 12pt;\">你</span><span style=\"font-family: 宋体; font-size: 12pt;\">和</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小孩的</span><span style=\"font-family: 宋体; font-size: 12pt;\">共</span><span style=\"font-family: 宋体; font-size: 12pt;\">存空間</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">便</span><span style=\"font-family: 宋体; font-size: 12pt;\">要靠你們在日常生活中多加留意</span><span style=\"font-family: 宋体; font-size: 12pt;\">及</span><span style=\"font-family: 宋体; font-size: 12pt;\">了解牠們的個性。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp;&nbsp;</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">開放公用空間：</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小</span><span style=\"font-family: 宋体; font-size: 12pt;\">孩不喜歡拘束的空間，更不</span><span style=\"font-family: 宋体; font-size: 12pt;\">宜</span><span style=\"font-family: 宋体; font-size: 12pt;\">關在狹小的籠中飼養，牠們需要盡情的跑跳及玩樂，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以一定要有公共的空間如客飯廳，這樣毛</span><span style=\"font-family: 宋体; font-size: 12pt;\">小孩與主人有</span><span style=\"font-family: 宋体; font-size: 12pt;\">了互動關係才可更緊密。</span><span style=\"font-family: 宋体; font-size: 12pt;\">當然也有主人怕牠</span><span style=\"font-family: 宋体; font-size: 12pt;\">們在你</span><span style=\"font-family: 宋体; font-size: 12pt;\">不在家</span><span style=\"font-family: 宋体; font-size: 12pt;\">時搗蛋，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以若家中空間許可的話不妨建造一個獨立又舒適的寵物房或花園&nbsp;(只供狗隻<span style=\"font-family: Calibri;\">)</span>，這樣便不怕牠們</span><span style=\"font-family: 宋体; font-size: 12pt;\">攪</span><span style=\"font-family: 宋体; font-size: 12pt;\">破壞，而狗狗更可呼吸到新鮮空氣。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">不可進入的空間：</span><span style=\"font-family: 宋体; font-size: 12pt;\">雖說要多接觸毛小孩才可增加感情及更融洽，但是為了牠們的安全起見有些地方是牠們萬萬不可進入，如廚房由於有火種，萬一毛小孩不小心觸碰到火種或是正在烤煮的爐具也會釀成意外，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以有些位置絕對封閉</span><span style=\"font-family: 宋体; font-size: 12pt;\">或加建活動拉門、隔間或屏風。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">專屬貓屋/</span><span style=\"font-family: 宋体; font-size: 12pt;\">狗窩：</span><span style=\"font-family: 宋体; font-size: 12pt;\">我們有自己的床同樣牠們也需要個人空間，不論貓/狗也好牠們都要專屬的私人空間，而且只要配合牠們的身形便可，</span><span style=\"font-family: 宋体; font-size: 12pt;\">有</span><span style=\"font-family: 宋体; font-size: 12pt;\">合適的空間牠們才可感到安心，太大反而沒有安全感。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小孩的儲物空間：</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">除了要</span><span style=\"font-family: 宋体; font-size: 12pt;\">有</span><span style=\"font-family: 宋体; font-size: 12pt;\">牠們的個人空間之外，牠們與小孩子一樣也有不少專用的物品如清潔用品</span><span style=\"font-family: 宋体; font-size: 12pt;\">、零食、衣服、玩具、病歷等</span><span style=\"font-family: 宋体; font-size: 12pt;\">，萬一你</span><span style=\"font-family: 宋体; font-size: 12pt;\">不整理好也會淹沒整個家</span><span style=\"font-family: 宋体; font-size: 12pt;\">居</span><span style=\"font-family: 宋体; font-size: 12pt;\">，所以設計時也要考慮給牠們一個角落，把牠們的玩具用品一一放好。</span><span style=\"font-family: Calibri; font-size: 12pt;\"><img style=\"font-family: 宋体; float: left; margin: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba20016.jpg\" width=\"343\" height=\"258\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">廁所:</span><span style=\"font-family: 宋体; font-size: 12pt;\">不論任何的寵物也要注重衛生，</span><span style=\"font-family: 宋体; font-size: 12pt;\">狗狗的便便氣味可能較大一些，所以不少</span><span style=\"font-family: 宋体; font-size: 12pt;\">主人要帶牠們到戶外上</span><span style=\"font-family: 宋体; font-size: 12pt;\">廁所，但對於較忙碌的主人來說早上時間太長要</span><span style=\"font-family: 宋体; font-size: 12pt;\">牠們忍太久也不可</span><span style=\"font-family: 宋体; font-size: 12pt;\">，因此需要在室內設有狗狗的專用廁所位，同時也要考慮氣味的問題，要保持整體通風良好，最簡單便是廁所內長期開窗或</span><span style=\"font-family: 宋体; font-size: 12pt;\">設置</span><span style=\"font-family: 宋体; font-size: 12pt;\">抽</span><span style=\"font-family: 宋体; font-size: 12pt;\">風</span><span style=\"font-family: 宋体; font-size: 12pt;\">系統，當然露台</span><span style=\"font-family: 宋体; font-size: 12pt;\">亦</span><span style=\"font-family: 宋体; font-size: 12pt;\">是個不錯的選擇同樣要注意安全問題。而貓咪則要專用的貓砂盆，由於貓砂盆所需地方有限，所以不妨考慮把貓砂盆與浴室洗手盆櫃子結合在下方位置再加上活動門方便清潔，不但可增加其私隱性，更可隔絕氣味。</span></p>\r\n<p class=\"15\" style=\"margin-left: 42pt; text-indent: -18pt;\">&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<table style=\"height: 168px; width: 195px; border-collapse: collapse; float: right;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"height: 291px;\">\r\n<td style=\"width: 203px; height: 459px; border-style: none;\">\r\n<p><img style=\"font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba468dc.jpg\" width=\"193\" height=\"193\" /><img style=\"font-family: 宋体; font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba04781.jpg\" width=\"193\" height=\"291\" /></p>\r\n<p><img style=\"font-family: 宋体; font-size: 12pt; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba500a3.jpg\" width=\"194\" height=\"129\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">&nbsp; &nbsp;毛孩已不</span><span style=\"font-family: 宋体; font-size: 12pt;\">只</span><span style=\"font-family: 宋体; font-size: 12pt;\">是寵物，</span><span style=\"font-family: 宋体; font-size: 12pt;\">而是我們生活</span><span style=\"font-family: 宋体; font-size: 12pt;\">或</span><span style=\"font-family: 宋体; font-size: 12pt;\">家中</span><span style=\"font-family: 宋体; font-size: 12pt;\">的一份子</span><span style=\"font-family: 宋体; font-size: 12pt;\">，猶如親生孩子一樣</span><span style=\"font-family: 宋体; font-size: 12pt;\">，對於牠們的生活所需、健康等問題也需要細心照料，</span><span style=\"font-family: 宋体; font-size: 12pt;\">除基本飲食外</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">生活環境更為重要，所以在設計規劃時也要考慮到牠們所需。我們可先</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: 宋体; font-size: 12pt;\">說一下牠們</span><span style=\"font-family: 宋体; font-size: 12pt;\">共</span><span style=\"font-family: 宋体; font-size: 12pt;\">通的特色</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">好讓大家在設計時</span><span style=\"font-family: 宋体; font-size: 12pt;\">有所</span><span style=\"font-family: 宋体; font-size: 12pt;\">考慮</span><span style=\"font-family: Calibri; font-size: 12pt;\">;</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">但要打造出</span><span style=\"font-family: 宋体; font-size: 12pt;\">既</span><span style=\"font-family: 宋体; font-size: 12pt;\">適</span><span style=\"font-family: 宋体; font-size: 12pt;\">合</span><span style=\"font-family: 宋体; font-size: 12pt;\">你</span><span style=\"font-family: 宋体; font-size: 12pt;\">和</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小孩的</span><span style=\"font-family: 宋体; font-size: 12pt;\">共</span><span style=\"font-family: 宋体; font-size: 12pt;\">存空間</span><span style=\"font-family: 宋体; font-size: 12pt;\">，</span><span style=\"font-family: 宋体; font-size: 12pt;\">便</span><span style=\"font-family: 宋体; font-size: 12pt;\">要靠你們在日常生活中多加留意</span><span style=\"font-family: 宋体; font-size: 12pt;\">及</span><span style=\"font-family: 宋体; font-size: 12pt;\">了解牠們的個性。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp;&nbsp;</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">開放公用空間：</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小</span><span style=\"font-family: 宋体; font-size: 12pt;\">孩不喜歡拘束的空間，更不</span><span style=\"font-family: 宋体; font-size: 12pt;\">宜</span><span style=\"font-family: 宋体; font-size: 12pt;\">關在狹小的籠中飼養，牠們需要盡情的跑跳及玩樂，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以一定要有公共的空間如客飯廳，這樣毛</span><span style=\"font-family: 宋体; font-size: 12pt;\">小孩與主人有</span><span style=\"font-family: 宋体; font-size: 12pt;\">了互動關係才可更緊密。</span><span style=\"font-family: 宋体; font-size: 12pt;\">當然也有主人怕牠</span><span style=\"font-family: 宋体; font-size: 12pt;\">們在你</span><span style=\"font-family: 宋体; font-size: 12pt;\">不在家</span><span style=\"font-family: 宋体; font-size: 12pt;\">時搗蛋，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以若家中空間許可的話不妨建造一個獨立又舒適的寵物房或花園&nbsp;(只供狗隻<span style=\"font-family: Calibri;\">)</span>，這樣便不怕牠們</span><span style=\"font-family: 宋体; font-size: 12pt;\">攪</span><span style=\"font-family: 宋体; font-size: 12pt;\">破壞，而狗狗更可呼吸到新鮮空氣。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">不可進入的空間：</span><span style=\"font-family: 宋体; font-size: 12pt;\">雖說要多接觸毛小孩才可增加感情及更融洽，但是為了牠們的安全起見有些地方是牠們萬萬不可進入，如廚房由於有火種，萬一毛小孩不小心觸碰到火種或是正在烤煮的爐具也會釀成意外，</span><span style=\"font-family: 宋体; font-size: 12pt;\">所以有些位置絕對封閉</span><span style=\"font-family: 宋体; font-size: 12pt;\">或加建活動拉門、隔間或屏風。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">專屬貓屋/</span><span style=\"font-family: 宋体; font-size: 12pt;\">狗窩：</span><span style=\"font-family: 宋体; font-size: 12pt;\">我們有自己的床同樣牠們也需要個人空間，不論貓/狗也好牠們都要專屬的私人空間，而且只要配合牠們的身形便可，</span><span style=\"font-family: 宋体; font-size: 12pt;\">有</span><span style=\"font-family: 宋体; font-size: 12pt;\">合適的空間牠們才可感到安心，太大反而沒有安全感。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"font-family: 宋体; font-size: 12pt;\">毛小孩的儲物空間：</span><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">除了要</span><span style=\"font-family: 宋体; font-size: 12pt;\">有</span><span style=\"font-family: 宋体; font-size: 12pt;\">牠們的個人空間之外，牠們與小孩子一樣也有不少專用的物品如清潔用品</span><span style=\"font-family: 宋体; font-size: 12pt;\">、零食、衣服、玩具、病歷等</span><span style=\"font-family: 宋体; font-size: 12pt;\">，萬一你</span><span style=\"font-family: 宋体; font-size: 12pt;\">不整理好也會淹沒整個家</span><span style=\"font-family: 宋体; font-size: 12pt;\">居</span><span style=\"font-family: 宋体; font-size: 12pt;\">，所以設計時也要考慮給牠們一個角落，把牠們的玩具用品一一放好。</span><span style=\"font-family: Calibri; font-size: 12pt;\"><img style=\"font-family: 宋体; float: left; margin: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8eba20016.jpg\" width=\"343\" height=\"258\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Calibri; font-size: 12pt;\">&nbsp; &nbsp; &nbsp; &nbsp;&middot;&nbsp;</span><span style=\"font-family: 宋体; font-size: 12pt;\">廁所:</span><span style=\"font-family: 宋体; font-size: 12pt;\">不論任何的寵物也要注重衛生，</span><span style=\"font-family: 宋体; font-size: 12pt;\">狗狗的便便氣味可能較大一些，所以不少</span><span style=\"font-family: 宋体; font-size: 12pt;\">主人要帶牠們到戶外上</span><span style=\"font-family: 宋体; font-size: 12pt;\">廁所，但對於較忙碌的主人來說早上時間太長要</span><span style=\"font-family: 宋体; font-size: 12pt;\">牠們忍太久也不可</span><span style=\"font-family: 宋体; font-size: 12pt;\">，因此需要在室內設有狗狗的專用廁所位，同時也要考慮氣味的問題，要保持整體通風良好，最簡單便是廁所內長期開窗或</span><span style=\"font-family: 宋体; font-size: 12pt;\">設置</span><span style=\"font-family: 宋体; font-size: 12pt;\">抽</span><span style=\"font-family: 宋体; font-size: 12pt;\">風</span><span style=\"font-family: 宋体; font-size: 12pt;\">系統，當然露台</span><span style=\"font-family: 宋体; font-size: 12pt;\">亦</span><span style=\"font-family: 宋体; font-size: 12pt;\">是個不錯的選擇同樣要注意安全問題。而貓咪則要專用的貓砂盆，由於貓砂盆所需地方有限，所以不妨考慮把貓砂盆與浴室洗手盆櫃子結合在下方位置再加上活動門方便清潔，不但可增加其私隱性，更可隔絕氣味。</span></p>\r\n<p class=\"15\" style=\"margin-left: 42pt; text-indent: -18pt;\">&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\">&nbsp;</p>\r\n</body>\r\n</html>', '[\"827\"]', '18', '1');
INSERT INTO `mg_z_column` VALUES ('21', '我與毛孩的生活 (下)', '我與毛孩的生活 (下)', '622期', '622期', '832', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img src=\"/mas_studio/storage/image/20180103/5a4c8feac3973.jpg\" alt=\"\" width=\"415\" height=\"277\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c8feb054be.jpg\" alt=\"\" width=\"388\" height=\"277\" /></span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;我與毛孩的生活</span> (<span style=\"font-family: 宋体;\">下</span><span style=\"font-family: Calibri;\">)</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp; &nbsp;上期我們說如何打造出一個合適與毛小孩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">共</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">存</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">生活空間，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">與及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">開放公用空間如何令到你們的關可更加融洽</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">牠們的專屬個人貓屋</span> /</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">狗窩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">儲物空間及廁所位置等等，而我們這一期繼續討論室內的裝修及傢俬</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">地台及牆身飾面</span> </span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash; </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">有毛小孩的朋友也會考慮萬一牠們不慎在地板上小便要清潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">十分麻煩，要是用上木地板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">而未</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">及時發現</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">清潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">地板便會吸入小便，不但氣味難以清潔嚴重的話更會變色及谷起。若選用了地毯問題便更嚴重了，需要更多時間來處理在地毯上的</span>p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">oo poo </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">同</span> </span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Wee Wee </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，日子久了更容易有寄生蟲在地毯內，這樣對主人和毛小孩也造成影響，所以地台飾面建議用上容易清潔的瓷</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">磚、石材最好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">。</span> <span style=\"font-family: 宋体;\">而牆身選用的物料同樣也要考慮到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Century Gothic\'; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">`</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">便便</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Century Gothic\'; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&acute;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">及搗蛋的問題，不妨選用乳膠漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不鏽鋼、膠板、石材、玻璃</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">，也可防止</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">被</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">寵物抓傷破壞之餘</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">較容易清潔。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">傢俬</span> </span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash; </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">不少毛小孩特別貓咪喜愛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">磨</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">抓，所以傢俬最好用上木材避免選擇布藝或皮革。不過對於養貓咪的主人來說，沙發選用真皮</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">或布料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">往往</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">無一幸免的，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">然而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">選用布料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">好處</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">是可以更換及清洗，總比</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">更換</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">全新的來得化算。而窗簾也是常被用來磨抓的大玩具之一，不妨選用卷簾同時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">但注意要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">收好窗簾的繩子</span> ~</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">牠們的至愛。當然愛玩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">是牠們的天性，你也希望牠們每天開開心心的生活，簡單的可以買現有的貓咪跳台玩具。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">玩具與傢俬合二為一</span> </span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash; </span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">如上述提及貓咪與狗狗不同，狗狗每天需要外出散步，但貓咪只會留在家中，而且喜愛跳來跳去，又喜愛在高處探視你的一舉一動，如重新裝修及設計時不妨在牆身或傢俱設計出不同高度的</span><span style=\"font-family: 宋体;\">跳台</span><span style=\"font-family: 宋体;\">或者貓咪專屬通道，把傢俬融合成為貓咪的大玩具，牠們一定愛不釋手同時又可節省地方一舉兩得。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><!-- [if !supportLists]--><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">最後一點是安全問題，家中有不少危險物品如塑膠袋、電拖板、打火機等，看似微不足道的日常物品，對毛小孩來說都可能是不同的陷阱，防不勝防。所以主人們要把零碎物件好好收藏，避免毛小孩觸碰到。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\"><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8feaa9bc1.jpeg\" alt=\"\" width=\"239\" height=\"173\" /><img style=\"float: left; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8feadbff2.jpg\" width=\"173\" height=\"173\" />&nbsp; &nbsp;以上提出不同的注意事項可讓主人們在裝修設計前考慮到毛小孩的需要，好讓打造出一個溫暖共</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">融</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">的家。不過即使你設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">如何</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">華麗也好對毛小孩來說，牠只有一個親人，與你的相處時刻是任何更貴的玩具也不能</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">取代的，而且牠們只等同一個</span>2<span style=\"font-family: 宋体;\">歲小孩難免會有犯錯或在你心情不好的時候觸犯到你而牠們也不知，你要對牠們特別的包容，若果你不可承諾照顧牠們一生的話千萬不要嘗試飼養，牠們不是玩具更不是禮品，請支持領養。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: 宋体;\">&nbsp;</span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><img src=\"/mas_studio/storage/image/20180103/5a4c8feac3973.jpg\" alt=\"\" width=\"415\" height=\"277\" />&nbsp;<img src=\"/mas_studio/storage/image/20180103/5a4c8feb054be.jpg\" alt=\"\" width=\"388\" height=\"277\" /></span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;我與毛孩的生活</span>&nbsp;(<span>下</span><span style=\"font-family: Calibri;\">)</span></span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp; &nbsp;上期我們說如何打造出一個合適與毛小孩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>共</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>存</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>生活空間，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>與及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>開放公用空間如何令到你們的關可更加融洽</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>牠們的專屬個人貓屋</span>&nbsp;/</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>狗窩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>儲物空間及廁所位置等等，而我們這一期繼續討論室內的裝修及傢俬</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>地台及牆身飾面</span>&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>有毛小孩的朋友也會考慮萬一牠們不慎在地板上小便要清潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>十分麻煩，要是用上木地板</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>而未</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>及時發現</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>和</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>清潔</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>地板便會吸入小便，不但氣味難以清潔嚴重的話更會變色及谷起。若選用了地毯問題便更嚴重了，需要更多時間來處理在地毯上的</span>p</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">oo poo&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>同</span>&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">Wee Wee&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，日子久了更容易有寄生蟲在地毯內，這樣對主人和毛小孩也造成影響，所以地台飾面建議用上容易清潔的瓷</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>磚、石材最好</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。</span>&nbsp;<span>而牆身選用的物料同樣也要考慮到</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Century Gothic\'; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">`</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>便便</span></span><span style=\"mso-spacerun: \'yes\'; font-family: \'Century Gothic\'; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&acute;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>及搗蛋的問題，不妨選用乳膠漆</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>、</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>不鏽鋼、膠板、石材、玻璃</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，也可防止</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>被</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>寵物抓傷破壞之餘</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>較容易清潔。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>傢俬</span>&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>不少毛小孩特別貓咪喜愛</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>磨</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>抓，所以傢俬最好用上木材避免選擇布藝或皮革。不過對於養貓咪的主人來說，沙發選用真皮</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>或布料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>往往</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>是</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>無一幸免的，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>然而</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>選用布料</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>好處</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>是可以更換及清洗，總比</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>更換</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>全新的來得化算。而窗簾也是常被用來磨抓的大玩具之一，不妨選用卷簾同時</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>但注意要</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>收好窗簾的繩子</span>&nbsp;~</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>牠們的至愛。當然愛玩</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>亦</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>是牠們的天性，你也希望牠們每天開開心心的生活，簡單的可以買現有的貓咪跳台玩具。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>玩具與傢俬合二為一</span>&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&ndash;&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>如上述提及貓咪與狗狗不同，狗狗每天需要外出散步，但貓咪只會留在家中，而且喜愛跳來跳去，又喜愛在高處探視你的一舉一動，如重新裝修及設計時不妨在牆身或傢俱設計出不同高度的</span><span>跳台</span><span>或者貓咪專屬通道，把傢俬融合成為貓咪的大玩具，牠們一定愛不釋手同時又可節省地方一舉兩得。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>最後一點是安全問題，家中有不少危險物品如塑膠袋、電拖板、打火機等，看似微不足道的日常物品，對毛小孩來說都可能是不同的陷阱，防不勝防。所以主人們要把零碎物件好好收藏，避免毛小孩觸碰到。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c8feaa9bc1.jpeg\" alt=\"\" width=\"239\" height=\"173\" /><img style=\"float: left; margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c8feadbff2.jpg\" width=\"173\" height=\"173\" />&nbsp; &nbsp;以上提出不同的注意事項可讓主人們在裝修設計前考慮到毛小孩的需要，好讓打造出一個溫暖共</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>融</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的家。不過即使你設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>如何</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>華麗也好對毛小孩來說，牠只有一個親人，與你的相處時刻是任何更貴的玩具也不能</span></span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>取代的，而且牠們只等同一個</span>2<span>歲小孩難免會有犯錯或在你心情不好的時候觸犯到你而牠們也不知，你要對牠們特別的包容，若果你不可承諾照顧牠們一生的話千萬不要嘗試飼養，牠們不是玩具更不是禮品，請支持領養。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\">&nbsp;</p>\r\n<p class=\"15\" style=\"margin-left: 42.0000pt; mso-para-margin-left: 0.0000gd;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"832\"]', '19', '1');
INSERT INTO `mg_z_column` VALUES ('22', '樓·梯 (上)', '樓·梯 (上)', '623期', '623期', '838', '1514908800', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 16px;\">&nbsp;</span><span style=\"font-family: PMingLiU; font-size: 16px;\">&nbsp;</span></p>\r\n<table style=\"width: 470px; border-collapse: collapse; float: right; height: 215px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 314px;\">\r\n<td style=\"width: 271px; height: 314px;\">\r\n<p><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc13873.jpg\" alt=\"\" width=\"122\" height=\"164\" />&nbsp;<img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc2bd24.jpg\" alt=\"\" width=\"141\" height=\"165\" /></p>\r\n<p><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c925a91d96.jpg\" alt=\"\" width=\"129\" height=\"167\" />&nbsp;<img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c925aaf23a.jpg\" alt=\"\" width=\"131\" height=\"167\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><br />　</span><span style=\"font-family: 宋体;\">　</span>樓梯 ，把兩個上下不同空間的連接通道，但隨著生活水準的提高，大家對樓梯的設計也不單單講求結構合理、安全及實用更需要美觀。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>雖然設計樓梯要按現場的情況，多數人也會盡量佔用最少的空間，但樓梯每級踏步的比例也會影響到安全，一般樓梯的斜度在30度左右，這個角度是最符合人上下樓梯的習慣的， 這個角度也考慮到了老人與小孩的關係。當然特殊功能的樓梯要求的斜度也各不相同，例如爬梯的坡度在60度以上，專用樓梯則可45度</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">至</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">60度等等。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>當然香港法律對樓梯的設計也有要求就是樓梯每級平面最少要有225</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">深</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">及每級高度不可多於175</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、如多於16</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">級樓梯要加設平台、一邊或兩邊要安裝扶手，如果是圓形的扶手不可少於38</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也不可多於50</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，如矩形的扶手闊度不可少於40</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也不可多於50</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，而扶手的高度要在850</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm &ndash; 950 mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">高。而欄杆的間距，即兩根欄杆的中心距離不要大於100</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，以防止小童的頭容易伸出去。另外高度不可少於2米、闊度最少900m</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">m</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，但闊度最好考慮到是否可滿足人行走舒適、傢具搬運方便。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>但法</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">例</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的尺寸也只是最基本</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要求，而每級的平面深度最好有280</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;3</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">20</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">因為這是最起碼要適應成人的腳掌尺寸，當然深一點也安全些，但太多又會浪費空間，而高度最少也有150</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">便最好。另外特別要注意梯級不可忽高忽低，因為人在上、下樓的時候，那種節奏感已經在腦袋裡存好了，成為一種很自然的事，這時候如果突然梯級</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的高度有別便會有</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">踩空的感覺，會使人產生驚嚇並易生意外。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp;</span></p>\r\n<table style=\"width: 404px; border-collapse: collapse; float: left; height: 208px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 340px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c90fbefd1f.jpg\" alt=\"\" width=\"159\" height=\"234\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc83b03.jpg\" width=\"156\" height=\"234\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>除了人體工學的尺寸之外也要考慮安全性問題，首先是承重量，</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">尤其</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">是特別設計及加建的樓梯當然要找專業的工程師先計算好，能否承受家人之「重」量。其次也要考慮防滑問題，如加上防滑條、金屬顆粒/條或者磨砂/造凹糟等，並且確實樓梯的所有部件應圓滑，沒有突出尖銳的位置，以免對家人及小童造成傷害。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;</span></p>\r\n<p><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 16px;\">&nbsp; &nbsp;</span><span style=\"font-family: PMingLiU; font-size: 16px;\">&nbsp;</span></p>\r\n<table style=\"width: 470px; border-collapse: collapse; float: right; height: 215px;\" border=\"0\">\r\n<tbody>\r\n<tr style=\"height: 314px;\">\r\n<td style=\"width: 295px; height: 314px;\">\r\n<p><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc13873.jpg\" alt=\"\" width=\"122\" height=\"164\" /><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc2bd24.jpg\" alt=\"\" width=\"141\" height=\"165\" /></p>\r\n<p><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c925a91d96.jpg\" alt=\"\" width=\"129\" height=\"167\" /><img style=\"font-family: PMingLiU; font-size: 16px;\" src=\"/mas_studio/storage/image/20180103/5a4c925aaf23a.jpg\" alt=\"\" width=\"131\" height=\"167\" /></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>樓梯 ，把兩個上下不同空間的連接通道，但隨著生活水準的提高，大家對樓梯的設計也不單單講求結構合理、安全及實用更需要美觀。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>雖然設計樓梯要按現場的情況，多數人也會盡量佔用最少的空間，但樓梯每級踏步的比例也會影響到安全，一般樓梯的斜度在30度左右，這個角度是最符合人上下樓梯的習慣的， 這個角度也考慮到了老人與小孩的關係。當然特殊功能的樓梯要求的斜度也各不相同，例如爬梯的坡度在60度以上，專用樓梯則可45度</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">至</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">60度等等。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>當然香港法律對樓梯的設計也有要求就是樓梯每級平面最少要有225</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">深</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">及每級高度不可多於175</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">、如多於16</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">級樓梯要加設平台、一邊或兩邊要安裝扶手，如果是圓形的扶手不可少於38</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也不可多於50</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，如矩形的扶手闊度不可少於40</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">也不可多於50</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，而扶手的高度要在850</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm &ndash; 950 mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">高。而欄杆的間距，即兩根欄杆的中心距離不要大於100</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，以防止小童的頭容易伸出去。另外高度不可少於2米、闊度最少900m</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">m</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">，但闊度最好考慮到是否可滿足人行走舒適、傢具搬運方便。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>但法</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">例</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的尺寸也只是最基本</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">要求，而每級的平面深度最好有280</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">-</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;3</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">20</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">因為這是最起碼要適應成人的腳掌尺寸，當然深一點也安全些，但太多又會浪費空間，而高度最少也有150</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">mm&nbsp;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">便最好。另外特別要注意梯級不可忽高忽低，因為人在上、下樓的時候，那種節奏感已經在腦袋裡存好了，成為一種很自然的事，這時候如果突然梯級</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的高度有別便會有</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">踩空的感覺，會使人產生驚嚇並易生意外。</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp; &nbsp;</span></p>\r\n<table style=\"width: 404px; border-collapse: collapse; float: left; height: 208px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 340px;\"><img src=\"/mas_studio/storage/image/20180103/5a4c90fbefd1f.jpg\" alt=\"\" width=\"159\" height=\"234\" /><img style=\"margin-right: 5px; margin-left: 5px;\" src=\"/mas_studio/storage/image/20180103/5a4c90fc83b03.jpg\" width=\"156\" height=\"234\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>除了人體工學的尺寸之外也要考慮安全性問題，首先是承重量，</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">尤其</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">是特別設計及加建的樓梯當然要找專業的工程師先計算好，能否承受家人之「重」量。其次也要考慮防滑問題，如加上防滑條、金屬顆粒/條或者磨砂/造凹糟等，並且確實樓梯的所有部件應圓滑，沒有突出尖銳的位置，以免對家人及小童造成傷害。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp; &nbsp;</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n</body>\r\n</html>', '[\"838\"]', '20', '1');
INSERT INTO `mg_z_column` VALUES ('23', '樓·梯 (下)', '樓·梯 (下)', '624期', '624期', '841', '1519315200', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">&nbsp;&nbsp;</span></span></p>\r\n<p><img style=\"float: right; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c933178795.jpg\" width=\"206\" height=\"309\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c933146ded.jpg\" alt=\"\" width=\"205\" height=\"307\" /><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>上期和大家提到設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">樓梯時要了解</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">基本的尺寸及注意的事項等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">，這一期我們則講解一下樓梯的設計款式及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">物料等</span>;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>樓梯的設計主要有</span>3類 :</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">直梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">最常見、最簡單，需要轉角時只要加上平台便可，但給予人較硬的感覺；</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">弧型梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">利用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">曲線打造出寬闊又美觀的樓梯，而且行走起來最為舒服</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: PMingLiU; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">;</span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><!--[endif]--><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">旋轉梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">這是佔用空間最小的設計，所以對狹小的空間來說，選用旋轉梯是比較明智的選擇。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>另外在設計樓梯時也要考慮到樓梯下空間如何可以充分的使用，通常會加建牆身造成儲物室，也有部分家庭會在樓梯下較高的位置建造小客廁或者工人</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">房</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">。當然有足夠的空間會在樓梯下放置藝術品或植物，具有調節空間擺設及氣氛的效果。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>而樓梯也有多種不同的製造方法</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span style=\"font-family: PMingLiU;\">混凝土樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>香港大部份樓宇也正在使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">現澆式鋼筋混凝土樓梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">，但由於建造</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">的方法</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">較複雜，施工</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">速度慢</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">不過</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">堅固耐用及最安全，而且走動也不會發</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">出聲</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">響</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">及擺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">動。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span style=\"font-family: PMingLiU;\">金屬製樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>雖說是金屬製樓梯但一般也會在樓梯板加上木材混合而成，如扶手和護欄是金屬製品，樓梯板仍為木製品，也有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">些</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">護欄為金屬製品，扶手和樓梯板採用木製品，而金屬製的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">護</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">有很多不同的花紋選擇。</span> </span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>另外全金屬製的樓梯在使用時可能會發出過大的噪音，特別在夜深人靜的時候更是可怕的。所以樓梯的噪音與梯級踏步的材質及整體設計也有關係，這點要注意。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span style=\"font-family: PMingLiU;\">木製樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>由於木材本身給予人溫暖感，加上地板材質和色彩容易搭配，施工和保養也十分方便，但日子久了有機會</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: PMingLiU;\">發</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: PMingLiU;\">出聲</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: PMingLiU;\">響</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: PMingLiU;\">及擺</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span style=\"font-family: PMingLiU;\">動</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">。為了有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">效</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">使用空間所以在設計上有不少木製樓梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">便</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">合併成櫃子，有更多的儲物空間。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt;\">磚砌樓梯</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>使用比較少，一般只用在加建幾級的情況下使用，造型比較刻板也沒有什麼設計可言，而且不能有效利用空間。</span></span></p>\r\n<p><img style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: 14px; float: left; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c933128e93.jpg\" width=\"229\" height=\"331\" /></p>\r\n<p><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c9331612f0.jpg\" alt=\"\" width=\"344\" height=\"332\" /></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span style=\"font-family: PMingLiU;\">玻璃樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>而這幾年特別a</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">pple store用上玻璃樓梯之後，便有不少年青人選</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">用</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。另外因為</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">防女士</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">走光及安全等問題，大</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">多會</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">用磨砂</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">及</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">不全透明</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">玻璃，厚度更在10mm以上。</span><span style=\"font-family: PMingLiU; font-size: 12pt;\">其實選擇什麼物料及如何設計也好，一定要找來專業的工程師計算及有經驗的承包商建造，這樣便萬無一失。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"font-family: PMingLiU;\">&nbsp;&nbsp;</span></span></p>\r\n</body>\r\n</html>', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp;&nbsp;</span></span></p>\r\n<p><img style=\"float: right; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c933178795.jpg\" width=\"206\" height=\"309\" /></p>\r\n<p><img style=\"float: right;\" src=\"/mas_studio/storage/image/20180103/5a4c933146ded.jpg\" alt=\"\" width=\"205\" height=\"307\" /><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>上期和大家提到設計</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>樓梯時要了解</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>基本的尺寸及注意的事項等</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，這一期我們則講解一下樓梯的設計款式及</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>物料等</span>;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>樓梯的設計主要有</span>3類 :</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>直梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>最常見、最簡單，需要轉角時只要加上平台便可，但給予人較硬的感覺；</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>弧型梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>利用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>曲線打造出寬闊又美觀的樓梯，而且行走起來最為舒服</span></span><span style=\"mso-spacerun: \'yes\'; font-family: Calibri; mso-fareast-font-family: PMingLiU; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">;</span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>&middot;</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>旋轉梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">：</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>這是佔用空間最小的設計，所以對狹小的空間來說，選用旋轉梯是比較明智的選擇。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>另外在設計樓梯時也要考慮到樓梯下空間如何可以充分的使用，通常會加建牆身造成儲物室，也有部分家庭會在樓梯下較高的位置建造小客廁或者工人</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>房</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。當然有足夠的空間會在樓梯下放置藝術品或植物，具有調節空間擺設及氣氛的效果。</span></span></p>\r\n<p class=\"15\" style=\"margin-left: 18.0000pt; mso-para-margin-left: 0.0000gd; text-indent: -18.0000pt; mso-list: l0 level1 lfo1;\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>而樓梯也有多種不同的製造方法</span>:</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span>混凝土樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>香港大部份樓宇也正在使用</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>現澆式鋼筋混凝土樓梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，但由於建造</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>的方法</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>較複雜，施工</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>速度慢</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>，</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>不過</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>堅固耐用及最安全，而且走動也不會發</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>出聲</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>響</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>及擺</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>動。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span>金屬製樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>雖說是金屬製樓梯但一般也會在樓梯板加上木材混合而成，如扶手和護欄是金屬製品，樓梯板仍為木製品，也有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>些</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>護欄為金屬製品，扶手和樓梯板採用木製品，而金屬製的</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>護</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>欄</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>也</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>有很多不同的花紋選擇。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>另外全金屬製的樓梯在使用時可能會發出過大的噪音，特別在夜深人靜的時候更是可怕的。所以樓梯的噪音與梯級踏步的材質及整體設計也有關係，這點要注意。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span>木製樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>由於木材本身給予人溫暖感，加上地板材質和色彩容易搭配，施工和保養也十分方便，但日子久了有機會</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span>發</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span>出聲</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span>響</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span>及擺</span></span><span style=\"font-family: PMingLiU; font-size: 12pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><span>動</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>。為了有</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>效</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>使用空間所以在設計上有不少木製樓梯</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>便</span></span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>合併成櫃子，有更多的儲物空間。</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt;\">磚砌樓梯</span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>使用比較少，一般只用在加建幾級的情況下使用，造型比較刻板也沒有什麼設計可言，而且不能有效利用空間。</span></span></p>\r\n<p><img style=\"font-family: Verdana, Arial, Helvetica, sans-serif; font-size: 14px; float: left; margin-right: 8px; margin-left: 8px;\" src=\"/mas_studio/storage/image/20180103/5a4c933128e93.jpg\" width=\"229\" height=\"331\" /></p>\r\n<p><img style=\"float: left;\" src=\"/mas_studio/storage/image/20180103/5a4c9331612f0.jpg\" alt=\"\" width=\"344\" height=\"332\" /></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: PMingLiU; font-size: 14pt;\"><span>玻璃樓梯</span></span></p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span style=\"mso-spacerun: \'yes\'; font-family: 宋体; mso-ascii-font-family: Calibri; mso-hansi-font-family: Calibri; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">　</span><span style=\"font-family: 宋体;\">　</span>而這幾年特別a</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">pple store用上玻璃樓梯之後，便有不少年青人選</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">用</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">。另外因為</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">防女士</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">走光及安全等問題，大</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">多會</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">用磨砂</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">及</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">不全透明</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">的</span><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\">玻璃，厚度更在10mm以上。</span><span style=\"font-family: PMingLiU; font-size: 12pt;\">其實選擇什麼物料及如何設計也好，一定要找來專業的工程師計算及有經驗的承包商建造，這樣便萬無一失。</span></p>\r\n<p class=\"MsoNormal\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"mso-spacerun: \'yes\'; font-family: PMingLiU; mso-bidi-font-family: \'Times New Roman\'; font-size: 12.0000pt; mso-font-kerning: 1.0000pt;\"><span>&nbsp;&nbsp;</span></span></p>\r\n</body>\r\n</html>', '[\"841\"]', '21', '1');

